Add the function to delete a logged entry. Give me an option to press on a entry to save it as a frequently used option. And give me the ability to go back and check a previous day, a calendar function. Make sure my logged info is saved in local storage. 


Here is the last good code you gave me. 

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
    <title>GlowTracker</title>
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet">
    <style>
        :root {
            --bg: #F2F2F7;
            --card: rgba(255, 255, 255, 0.8);
            --accent: #FF7E5F;
            --protein: #764BA2;
            --text: #1C1C1E;
            --spring: cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg);
            color: var(--text);
            padding-top: env(safe-area-inset-top);
            padding-bottom: env(safe-area-inset-bottom);
            overflow-x: hidden;
        }

        /* --- Magic Animations --- */
        @keyframes popIn {
            0% { transform: scale(0.8); opacity: 0; }
            100% { transform: scale(1); opacity: 1; }
        }

        .bounce-click:active { transform: scale(0.92); }
        .transition-all { transition: all 0.4s var(--spring); }

        /* --- Layout --- */
        .container {
            max-width: 400px;
            margin: 0 auto;
            padding: 20px;
        }

        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 25px;
        }

        .glass-card {
            background: var(--card);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border-radius: 24px;
            padding: 20px;
            box-shadow: 0 8px 32px rgba(0,0,0,0.05);
            margin-bottom: 20px;
            animation: popIn 0.5s var(--spring);
        }

        /* --- Rings & Stats --- */
        .summary-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 15px;
        }

        .ring-container {
            position: relative;
            width: 100px;
            height: 100px;
            margin: 0 auto;
        }

        svg { transform: rotate(-90deg); }
        circle {
            fill: none;
            stroke-width: 10;
            stroke-linecap: round;
            transition: stroke-dashoffset 1s var(--spring);
        }

        .avg-pill {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 8px 16px;
            border-radius: 50px;
            font-size: 0.8rem;
            font-weight: 600;
            display: inline-block;
        }

        /* --- Inputs --- */
        .input-group {
            display: flex;
            gap: 10px;
            margin-top: 20px;
        }

        input {
            background: rgba(0,0,0,0.05);
            border: none;
            padding: 15px;
            border-radius: 15px;
            width: 100%;
            font-size: 1rem;
            outline: none;
        }

        .add-btn {
            background: var(--text);
            color: white;
            border: none;
            width: 50px;
            border-radius: 15px;
            font-size: 1.5rem;
            cursor: pointer;
        }

        /* --- History List --- */
        .history-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 12px 0;
            border-bottom: 1px solid rgba(0,0,0,0.05);
        }

        .history-item:last-child { border: none; }

        .date-chip {
            font-size: 0.75rem;
            color: gray;
            margin-bottom: 4px;
        }

        /* --- Settings/Goal Overlay --- */
        #settings-modal {
            position: fixed;
            top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(0,0,0,0.4);
            backdrop-filter: blur(5px);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 100;
        }
    </style>
</head>
<body>

<div class="container">
    <header>
        <div>
            <h1 style="font-size: 1.8rem;">Hey! ✨</h1>
            <p id="today-date" style="color: gray;"></p>
        </div>
        <div class="bounce-click transition-all" onclick="toggleSettings()" style="font-size: 1.5rem; cursor: pointer;">
            ⚙️
        </div>
    </header>

    <!-- Weekly Average Card -->
    <div class="glass-card" style="text-align: center; background: linear-gradient(to bottom right, #ffffff, #f9f9f9);">
        <span class="avg-pill">Weekly Magic Average</span>
        <div style="margin-top: 15px; display: flex; justify-content: space-around;">
            <div>
                <h2 id="weekly-cal-avg">0</h2>
                <small>kcal</small>
            </div>
            <div>
                <h2 id="weekly-pro-avg">0</h2>
                <small>protein</small>
            </div>
        </div>
    </div>

    <!-- Daily Progress -->
    <div class="glass-card">
        <div class="summary-grid">
            <div class="ring-container">
                <svg width="100" height="100">
                    <circle cx="50" cy="50" r="40" stroke="#eee" />
                    <circle id="cal-ring" cx="50" cy="50" r="40" stroke="var(--accent)" stroke-dasharray="251.2" stroke-dashoffset="251.2" />
                </svg>
                <div style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); text-align: center;">
                    <span id="cur-cal" style="font-weight: bold;">0</span><br><small>kcal</small>
                </div>
            </div>
            <div class="ring-container">
                <svg width="100" height="100">
                    <circle cx="50" cy="50" r="40" stroke="#eee" />
                    <circle id="pro-ring" cx="50" cy="50" r="40" stroke="var(--protein)" stroke-dasharray="251.2" stroke-dashoffset="251.2" />
                </svg>
                <div style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); text-align: center;">
                    <span id="cur-pro" style="font-weight: bold;">0</span><br><small>prot</small>
                </div>
            </div>
        </div>

        <div class="input-group">
            <input type="number" id="input-cal" placeholder="Calories" inputmode="numeric">
            <input type="number" id="input-pro" placeholder="Protein" inputmode="numeric">
            <button class="add-btn bounce-click transition-all" onclick="addData()">+</button>
        </div>
    </div>

    <!-- History -->
    <h3 style="margin: 10px 0 15px 10px;">History</h3>
    <div id="history-list" class="glass-card">
        <!-- Items will appear here -->
    </div>
</div>

<!-- Modal for Goals -->
<div id="settings-modal">
    <div class="glass-card" style="width: 80%;">
        <h3>Set Daily Goals</h3>
        <br>
        <label>Daily Calories</label>
        <input type="number" id="goal-cal" placeholder="e.g. 2000">
        <br><br>
        <label>Daily Protein (g)</label>
        <input type="number" id="goal-pro" placeholder="e.g. 150">
        <br><br>
        <button class="add-btn" style="width: 100%; height: 50px;" onclick="saveGoals()">Save & Close</button>
    </div>
</div>

<script>
    let db = JSON.parse(localStorage.getItem('glowTracker')) || {
        history: [],
        goals: { cal: 2000, pro: 150 }
    };

    function init() {
        const d = new Date();
        document.getElementById('today-date').innerText = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
        document.getElementById('goal-cal').value = db.goals.cal;
        document.getElementById('goal-pro').value = db.goals.pro;
        updateUI();
    }

    function addData() {
        const cal = parseInt(document.getElementById('input-cal').value) || 0;
        const pro = parseInt(document.getElementById('input-pro').value) || 0;

        if (cal === 0 && pro === 0) return;

        const today = new Date().toISOString().split('T')[0];
        db.history.push({ date: today, cal, pro, ts: Date.now() });

        document.getElementById('input-cal').value = '';
        document.getElementById('input-pro').value = '';

        saveAndRefresh();

        // "Magic" feedback
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function updateUI() {
        const today = new Date().toISOString().split('T')[0];
        const todayLogs = db.history.filter(i => i.date === today);

        const totalCal = todayLogs.reduce((s, i) => s + i.cal, 0);
        const totalPro = todayLogs.reduce((s, i) => s + i.pro, 0);

        // Update Rings
        updateRing('cal-ring', totalCal, db.goals.cal);
        updateRing('pro-ring', totalPro, db.goals.pro);

        document.getElementById('cur-cal').innerText = totalCal;
        document.getElementById('cur-pro').innerText = totalPro;

        // Update History
        const list = document.getElementById('history-list');
        list.innerHTML = db.history.slice().reverse().slice(0, 7).map(i => `
            <div class="history-item">
                <div>
                    <div class="date-chip">${new Date(i.ts).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})} - ${i.date}</div>
                    <strong>${i.cal} kcal</strong>
                </div>
                <div style="color: var(--protein); font-weight: bold;">${i.pro}g Protein</div>
            </div>
        `).join('') || '<p style="text-align:center; color:gray;">No entries yet today ✨</p>';

        calculateAverages();
    }

    function updateRing(id, val, goal) {
        const circle = document.getElementById(id);
        const circumference = 2 * Math.PI * 40;
        const percent = Math.min(val / goal, 1);
        const offset = circumference - (percent * circumference);
        circle.style.strokeDashoffset = offset;
    }

    function calculateAverages() {
        const oneWeekAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);
        const weekEntries = db.history.filter(i => i.ts > oneWeekAgo);

        // Group by day to get daily totals for the week
        const dailyTotals = {};
        weekEntries.forEach(e => {
            dailyTotals[e.date] = dailyTotals[e.date] || {cal: 0, pro: 0};
            dailyTotals[e.date].cal += e.cal;
            dailyTotals[e.date].pro += e.pro;
        });

        const daysLogged = Object.keys(dailyTotals).length || 1;
        const sumCal = Object.values(dailyTotals).reduce((s, i) => s + i.cal, 0);
        const sumPro = Object.values(dailyTotals).reduce((s, i) => s + i.pro, 0);

        document.getElementById('weekly-cal-avg').innerText = Math.round(sumCal / daysLogged);
        document.getElementById('weekly-pro-avg').innerText = Math.round(sumPro / daysLogged);
    }

    function toggleSettings() {
        const m = document.getElementById('settings-modal');
        m.style.display = m.style.display === 'flex' ? 'none' : 'flex';
    }

    function saveGoals() {
        db.goals.cal = parseInt(document.getElementById('goal-cal').value) || 2000;
        db.goals.pro = parseInt(document.getElementById('goal-pro').value) || 150;
        saveAndRefresh();
        toggleSettings();
    }

    function saveAndRefresh() {
        localStorage.setItem('glowTracker', JSON.stringify(db));
        updateUI();
    }

    init();
</script>

</body>
</html>

