import React from 'react';

interface ProgressRingProps {
    radius: number;
    stroke: number;
    progress: number;
    color: string;
    label: string;
    subLabel: string;
    id: string;
}

const ProgressRing: React.FC<ProgressRingProps> = ({ radius, stroke, progress, color, label, subLabel, id }) => {
    const normalizedRadius = radius - stroke * 2;
    const circumference = normalizedRadius * 2 * Math.PI;
    const strokeDashoffset = circumference - (Math.min(progress, 1) * circumference);

    return (
        <div className="relative flex flex-col items-center justify-center">
            <svg
                height={radius * 2}
                width={radius * 2}
                className="transform -rotate-90 transition-all duration-500 ease-out"
            >
                {/* Background Ring */}
                <circle
                    stroke="#eee"
                    strokeWidth={stroke}
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                    strokeLinecap="round"
                />
                {/* Progress Ring */}
                <circle
                    stroke={color}
                    strokeWidth={stroke}
                    strokeDasharray={`${circumference} ${circumference}`}
                    style={{ strokeDashoffset }}
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                    strokeLinecap="round"
                    className="transition-all duration-1000 ease-[cubic-bezier(0.175,0.885,0.32,1.275)]"
                />
            </svg>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-center">
                <span className="block text-xl font-bold text-gray-800">{label}</span>
                <span className="block text-xs text-gray-500">{subLabel}</span>
            </div>
        </div>
    );
};

export default ProgressRing;

import React, { useState } from 'react';
import { Goals } from '../types';
import { X } from './Icons';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    currentGoals: Goals;
    onSave: (newGoals: Goals) => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, currentGoals, onSave }) => {
    const [cal, setCal] = useState(currentGoals.cal.toString());
    const [pro, setPro] = useState(currentGoals.pro.toString());

    if (!isOpen) return null;

    const handleSave = () => {
        onSave({
            cal: parseInt(cal) || 2000,
            pro: parseInt(pro) || 150
        });
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-fade-in p-4">
            <div className="bg-white/90 backdrop-blur-xl p-6 rounded-3xl shadow-2xl w-full max-w-sm animate-pop-in">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-gray-800">Your Goals</h3>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-600 mb-1">Daily Calories</label>
                        <input 
                            type="number" 
                            value={cal} 
                            onChange={(e) => setCal(e.target.value)}
                            className="w-full p-4 bg-gray-50 rounded-2xl border-none focus:ring-2 focus:ring-accent outline-none text-lg"
                            placeholder="2000"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-600 mb-1">Daily Protein (g)</label>
                        <input 
                            type="number" 
                            value={pro} 
                            onChange={(e) => setPro(e.target.value)}
                            className="w-full p-4 bg-gray-50 rounded-2xl border-none focus:ring-2 focus:ring-protein outline-none text-lg"
                            placeholder="150"
                        />
                    </div>
                </div>

                <button 
                    onClick={handleSave}
                    className="mt-8 w-full bg-black text-white py-4 rounded-2xl font-bold text-lg active:scale-95 transition-transform"
                >
                    Save Changes
                </button>
            </div>
        </div>
    );
};

export default SettingsModal;

import React from 'react';
