            </div>

            {/* History */}
            <div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 ml-2">History</h3>
                <div className="bg-white/60 backdrop-blur-lg rounded-[32px] p-2 border border-white/50 min-h-[100px] animate-slide-up">
                    {todaysLogs.length === 0 ? (
                        <div className="text-center py-8 text-gray-400">
                            No magic added for this date yet ✨
                        </div>
                    ) : (
                        todaysLogs.map((log) => (
                            <div key={log.id} className="group flex justify-between items-center p-4 mb-1 last:mb-0 rounded-2xl hover:bg-white/60 transition-colors">
                                <div>
                                    <div className="text-xs font-bold text-gray-400 mb-1">
                                        {new Date(log.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </div>
                                    <div className="flex items-baseline gap-2">
                                        <span className="font-bold text-lg text-gray-800">{log.cal} kcal</span>
                                        <span className="text-sm font-bold text-protein">{log.pro}g pro</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button 
                                        onClick={() => handleSavePreset(log)}
                                        className="p-3 text-gray-400 hover:text-yellow-500 hover:bg-yellow-50 rounded-xl transition"
                                        title="Save as Preset"
                                    >
                                        <Bookmark className="w-5 h-5" />
                                    </button>
                                    <button 
                                        onClick={() => handleDelete(log.id)}
                                        className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition"
                                        title="Delete Entry"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)} 
                currentGoals={goals} 
                onSave={setGoals} 
            />

            <PresetsModal 
                isOpen={showPresets} 
                onClose={() => setShowPresets(false)} 
                presets={presets}
                onSelect={handleSelectPreset}
                onDelete={handleDeletePreset}
            />
        </div>
    );
}

export default App;

