import React from 'react';

interface ProgressRingProps {
    radius: number;
    stroke: number;
    progress: number;
    color: string;
    label: string;
    subLabel: string;
    id: string;
}

const ProgressRing: React.FC<ProgressRingProps> = ({ radius, stroke, progress, color, label, subLabel }) => {
    const normalizedRadius = radius - stroke * 2;
    const circumference = normalizedRadius * 2 * Math.PI;

    // Ensure progress is valid number between 0 and 1
    const safeProgress = Number.isNaN(progress) || !Number.isFinite(progress) ? 0 : Math.min(Math.max(progress, 0), 1);
    const strokeDashoffset = circumference - (safeProgress * circumference);

    return (
        <div className="relative flex flex-col items-center justify-center">
            <svg
                height={radius * 2}
                width={radius * 2}
                className="transform -rotate-90"
            >
                {/* Background Ring */}
                <circle
                    stroke="#eee"
                    strokeWidth={stroke}
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                    strokeLinecap="round"
                />
                {/* Progress Ring */}
                <circle
                    stroke={color}
                    strokeWidth={stroke}
                    strokeDasharray={`${circumference} ${circumference}`}
                    style={{ strokeDashoffset }}
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                    strokeLinecap="round"
                    className="transition-[stroke-dashoffset] duration-700 ease-in-out"
                />
            </svg>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-center">
                <span className="block text-xl font-bold text-gray-800">{label}</span>
                <span className="block text-xs text-gray-500">{subLabel}</span>
            </div>
        </div>
    );
};

