                if (parsed.presets) setPresets(parsed.presets);

                // Handle migration from old 'goals' structure to new 'settings' structure
                if (parsed.settings) {
                    setSettings(parsed.settings);
                } else if (parsed.goals) {
                    setSettings({ ...DEFAULT_SETTINGS, goals: parsed.goals });
                }
            } catch (e) {
                console.error("Failed to load data", e);
            }
        }
    }, []);

    useEffect(() => {
        // Save current state structure, maintaining compatibility if needed
        localStorage.setItem('glowTracker', JSON.stringify({ 
            history, 
            settings, 
            presets 
        }));
    }, [history, settings, presets]);

    // --- Derived Data ---
    const dateKey = formatDateKey(currentDate);
