import React, { useState, useEffect } from 'react';
import { X, ChevronLeft, ChevronRight, Star } from './Icons';
import { LogEntry, Goals } from '../types';

interface CalendarModalProps {
    isOpen: boolean;
    onClose: () => void;
    currentDate: Date;
    onSelectDate: (date: Date) => void;
    history: LogEntry[];
    goals: Goals;
}

const CalendarModal: React.FC<CalendarModalProps> = ({ isOpen, onClose, currentDate, onSelectDate, history, goals }) => {
    const [viewDate, setViewDate] = useState(new Date());

    useEffect(() => {
        if (isOpen) {
            setViewDate(new Date(currentDate));
        }
    }, [isOpen, currentDate]);

    if (!isOpen) return null;

    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();

    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const days = [];
    // Padding
    for (let i = 0; i < firstDayOfMonth; i++) {
        days.push(null);
    }
    // Days
    for (let i = 1; i <= daysInMonth; i++) {
        days.push(i);
    }

    const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

    const changeMonth = (offset: number) => {
        const newDate = new Date(viewDate);
        newDate.setMonth(newDate.getMonth() + offset);
        setViewDate(newDate);
    };

    // Calculate daily status
    // Map: Day Number -> { cal: number, pro: number }
    const dailyData = new Map<number, { cal: number, pro: number }>();

    history.forEach(h => {
        const [entryYear, entryMonth, entryDay] = h.date.split('-').map(Number);
        // Ensure we only process this month's data
        if (entryYear === year && (entryMonth - 1) === month) {
            const existing = dailyData.get(entryDay) || { cal: 0, pro: 0 };
            dailyData.set(entryDay, {
                cal: existing.cal + h.cal,
                pro: existing.pro + h.pro
            });
        }
    });

    const getStatus = (day: number) => {
        const data = dailyData.get(day);
        if (!data) return 'none';

        const metCal = data.cal > 0 && data.cal <= (goals.cal || 2000);
        const metPro = data.pro >= (goals.pro || 150);

        if (metCal && metPro) return 'star'; // Perfect day
        if (metCal || metPro) return 'good'; // Partial success
        return 'logged'; // Logged but missed goals
    };

    return (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
             <div className="bg-white/90 backdrop-blur-xl p-6 rounded-3xl shadow-2xl w-full max-w-sm animate-pop-in">
                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-gray-800">Select Date</h3>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                {/* Calendar Controls */}
                <div className="flex justify-between items-center mb-6 px-2">
                    <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 rounded-full transition">
                        <ChevronLeft className="w-5 h-5 text-gray-600" />
                    </button>
                    <span className="font-bold text-lg text-gray-800 w-32 text-center">
                        {monthNames[month]} {year}
                    </span>
                    <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 rounded-full transition">
                        <ChevronRight className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                {/* Weekdays */}
                <div className="grid grid-cols-7 mb-2 text-center">
                    {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(d => (
                        <div key={d} className="text-xs font-bold text-gray-400 py-2">
                            {d}
                        </div>
                    ))}
                </div>

                {/* Days Grid */}
                <div className="grid grid-cols-7 gap-1 mb-6">
                    {days.map((d, i) => {
                        if (d === null) return <div key={`empty-${i}`} />;

                        const isSelected = d === currentDate.getDate() && month === currentDate.getMonth() && year === currentDate.getFullYear();
                        const isToday = d === new Date().getDate() && month === new Date().getMonth() && year === new Date().getFullYear();
                        const status = getStatus(d as number);

                        return (
                            <button
                                key={d}
                                onClick={() => {
                                    const selected = new Date(year, month, d as number);
                                    onSelectDate(selected);
                                }}
                                className={`
                                    relative h-10 w-10 mx-auto rounded-full flex items-center justify-center text-sm font-medium transition-all
                                    ${isSelected ? 'bg-black text-white shadow-lg scale-105' : 'text-gray-700 hover:bg-gray-100'}
                                    ${isToday && !isSelected ? 'border-2 border-accent text-accent' : ''}
                                `}
                            >
                                {d}

                                {/* Indicators */}
                                {!isSelected && status === 'star' && (
                                    <div className="absolute -bottom-1 text-yellow-500 drop-shadow-sm">
                                        <Star className="w-3 h-3" filled={true} />
                                    </div>
                                )}
                                {!isSelected && status === 'good' && (
                                    <div className="absolute bottom-1.5 w-1.5 h-1.5 bg-indigo-500 rounded-full shadow-sm"></div>
                                )}
                                {!isSelected && status === 'logged' && (
                                    <div className="absolute bottom-1.5 w-1.5 h-1.5 bg-gray-300 rounded-full"></div>
                                )}
                            </button>
                        );
                    })}
                </div>

                {/* Legend */}
                <div className="flex justify-center gap-4 text-[10px] text-gray-500 font-medium">
                     <div className="flex items-center gap-1">
                        <Star className="w-3 h-3 text-yellow-500" filled={true} />
                        <span>Perfect</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                        <span>Goal Met</span>
                    </div>
                     <div className="flex items-center gap-1">
                        <div className="w-1.5 h-1.5 bg-gray-300 rounded-full"></div>
                        <span>Logged</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CalendarModal;

import React, { useState, useEffect, useMemo } from 'react';
import { LogEntry, Settings, Preset } from './types';
import { ChevronLeft, ChevronRight, SettingsIcon, BookOpen, Trash2, Bookmark } from './components/Icons';
import ProgressRing from './components/ProgressRing';
import SettingsModal from './components/SettingsModal';
import PresetsModal from './components/PresetsModal';
import SavePresetModal from './components/SavePresetModal';
import ConfirmModal from './components/ConfirmModal';
import CalendarModal from './components/CalendarModal';

// FIX: Use local time construction to prevent timezone shifting (UTC vs Local)
const formatDateKey = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

const getDisplayDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
};

const DEFAULT_SETTINGS: Settings = { 
    goals: { cal: 2000, pro: 150 },
    mode: 'both' 
};

function App() {
    // --- State ---
    const [history, setHistory] = useState<LogEntry[]>([]);
    const [settings, setSettings] = useState<Settings>(DEFAULT_SETTINGS);
    const [presets, setPresets] = useState<Preset[]>([]);
    const [currentDate, setCurrentDate] = useState<Date>(new Date());

    // Inputs
    const [inputCal, setInputCal] = useState('');
    const [inputPro, setInputPro] = useState('');

    // Modals & UI State
    const [showSettings, setShowSettings] = useState(false);
    const [showPresets, setShowPresets] = useState(false);
    const [showSaveModal, setShowSaveModal] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [showCalendar, setShowCalendar] = useState(false);

    // Staging Data
    const [entryToSave, setEntryToSave] = useState<LogEntry | null>(null);
    const [entryToDelete, setEntryToDelete] = useState<string | null>(null);

    // --- Persistence ---
    useEffect(() => {
        const stored = localStorage.getItem('glowTracker');
        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                if (parsed.history) setHistory(parsed.history);
                if (parsed.presets) setPresets(parsed.presets);
                if (parsed.settings) {
                    setSettings(parsed.settings);
                } else if (parsed.goals) {
                    setSettings({ ...DEFAULT_SETTINGS, goals: parsed.goals });
                }
            } catch (e) {
                console.error("Failed to load data", e);
            }
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('glowTracker', JSON.stringify({ 
            history, 
            settings, 
            presets 
        }));
    }, [history, settings, presets]);

    // --- Derived Data ---
    const dateKey = formatDateKey(currentDate);
    // Fix: Ensure "isToday" comparison uses local string generation
    const isToday = dateKey === formatDateKey(new Date());

    const todaysLogs = useMemo(() => {
        return history.filter(h => h.date === dateKey).sort((a, b) => b.ts - a.ts);
    }, [history, dateKey]);

    const stats = useMemo(() => {
        return todaysLogs.reduce((acc, log) => ({
            cal: acc.cal + log.cal,
            pro: acc.pro + log.pro
        }), { cal: 0, pro: 0 });
    }, [todaysLogs]);

    const weeklyAvg = useMemo(() => {
        const oneWeekAgo = new Date();
        oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
        const weekKey = oneWeekAgo.getTime();

        const relevant = history.filter(h => h.ts > weekKey);
        const daysMap: Record<string, {cal: number, pro: number}> = {};

        relevant.forEach(h => {
            if (!daysMap[h.date]) daysMap[h.date] = { cal: 0, pro: 0 };
            daysMap[h.date].cal += h.cal;
            daysMap[h.date].pro += h.pro;
        });

        const daysLogged = Object.keys(daysMap).length || 1;
        const total = Object.values(daysMap).reduce((acc, d) => ({ cal: acc.cal + d.cal, pro: acc.pro + d.pro }), { cal: 0, pro: 0 });

        return {
            cal: Math.round(total.cal / daysLogged),
            pro: Math.round(total.pro / daysLogged)
        };
    }, [history]);

    // --- Actions ---
    const handleAdd = (c?: number, p?: number) => {
        const cVal = c !== undefined ? c : parseInt(inputCal);
        const pVal = p !== undefined ? p : parseInt(inputPro);

        const cleanCal = isNaN(cVal) ? 0 : cVal;
        const cleanPro = isNaN(pVal) ? 0 : pVal;

        if (cleanCal === 0 && cleanPro === 0) return;

        const newEntry: LogEntry = {
            id: Date.now().toString() + Math.random().toString(),
            date: dateKey,
            ts: Date.now(),
            cal: cleanCal,
            pro: cleanPro,
        };

        setHistory(prev => [...prev, newEntry]);
        setInputCal('');
        setInputPro('');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const initiateDelete = (id: string) => {
        setEntryToDelete(id);
        setShowConfirmModal(true);
    };

    const confirmDelete = () => {
        if (entryToDelete) {
            setHistory(prev => prev.filter(h => h.id !== entryToDelete));
            setEntryToDelete(null);
        }
    };

    const initiateSavePreset = (entry: LogEntry) => {
        setEntryToSave(entry);
        setShowSaveModal(true);
    };

    const finalizeSavePreset = (name: string) => {
        if (entryToSave && name) {
            const newPreset: Preset = {
                id: Date.now().toString(),
                label: name,
                cal: entryToSave.cal,
                pro: entryToSave.pro
            };
            setPresets(prev => [...prev, newPreset]);
            setShowSaveModal(false);
            setEntryToSave(null);
        }
    };

    const handleDeletePreset = (id: string) => {
        setPresets(prev => prev.filter(p => p.id !== id));
    };

    const handleSelectPreset = (preset: Preset) => {
        handleAdd(preset.cal, preset.pro);
        setShowPresets(false);
    };

    const changeDate = (days: number) => {
        const next = new Date(currentDate);
        next.setDate(currentDate.getDate() + days);
        setCurrentDate(next);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setShowCalendar(false);
    };

    // --- Render Helpers ---
    const showCal = settings.mode === 'both' || settings.mode === 'cal';
    const showPro = settings.mode === 'both' || settings.mode === 'pro';

    return (
        <div className="min-h-screen pb-10 max-w-[480px] mx-auto px-5 pt-safe-top">
            {/* Header */}
            <header className="flex justify-between items-center py-6">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-gray-800">Hey! ✨</h1>
                    <div className="flex items-center gap-2 mt-1 text-gray-500 text-sm font-medium">
                        <button onClick={() => changeDate(-1)} className="p-1 hover:bg-gray-200 rounded-full transition">
                            <ChevronLeft className="w-4 h-4" />
                        </button>

                        <button 
                            onClick={() => setShowCalendar(true)}
                            className="px-2 py-1 -mx-2 hover:bg-white/50 rounded-lg transition active:scale-95 flex items-center gap-1"
                        >
                            <span>{isToday ? "Today, " : ""}{getDisplayDate(currentDate)}</span>
                        </button>

                        <button 
                            onClick={() => changeDate(1)} 
                            disabled={isToday}
                            className={`p-1 rounded-full transition ${isToday ? 'opacity-30 cursor-not-allowed' : 'hover:bg-gray-200'}`}
                        >
                            <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                </div>
                <button 
                    onClick={() => setShowSettings(true)} 
                    className="p-3 bg-white/50 rounded-2xl hover:bg-white transition shadow-sm active:scale-95"
                >
                    <SettingsIcon className="text-gray-700 w-6 h-6" />
                </button>
            </header>

            {/* Weekly Stats */}
            <div className="bg-white/60 backdrop-blur-xl rounded-[32px] p-6 shadow-sm border border-white/50 mb-6 animate-pop-in">
                <div className="inline-block px-4 py-2 rounded-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white text-xs font-bold mb-4 shadow-md shadow-indigo-500/20">
                    WEEKLY AVERAGE
                </div>
                <div className={`flex justify-around items-center ${!showCal || !showPro ? 'justify-center' : ''}`}>
                    {showCal && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-gray-800">{weeklyAvg.cal}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Kcal</span>
                        </div>
                    )}
                    {showCal && showPro && <div className="w-px h-10 bg-gray-200"></div>}
                    {showPro && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-protein">{weeklyAvg.pro}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Protein</span>
                        </div>
                    )}
                </div>
            </div>

            {/* Rings & Input */}
            <div className="bg-white/80 backdrop-blur-xl rounded-[32px] p-6 shadow-lg shadow-gray-200/50 mb-8 border border-white animate-pop-in [animation-delay:100ms]">
                <div className={`grid gap-4 mb-8 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1 justify-items-center'}`}>
                    {showCal && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.cal / (settings.goals.cal || 1)} 
                            type="cal"
                            label={stats.cal.toString()} 
                            subLabel="kcal"
                        />
                    )}
                    {showPro && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.pro / (settings.goals.pro || 1)} 
                            type="pro"
                            label={stats.pro.toString()} 
                            subLabel="protein"
                        />
                    )}
                </div>

                <div className="flex gap-3">
                    <div className={`flex-1 grid gap-3 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1'}`}>
                        {showCal && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Cal" 
                                value={inputCal}
                                onChange={(e) => setInputCal(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-accent outline-none transition-all"
                            />
                        )}
                        {showPro && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Pro" 
                                value={inputPro}
                                onChange={(e) => setInputPro(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-protein outline-none transition-all"
                            />
                        )}
                    </div>
                    <div className="flex flex-col gap-2">
                        <button 
                            onClick={() => handleAdd()} 
                            className="h-full bg-gray-900 text-white rounded-2xl px-5 font-bold text-2xl active:scale-95 transition-transform shadow-lg shadow-gray-900/20"
                        >
                            +
                        </button>
                    </div>
                </div>
                 <button 
                    onClick={() => setShowPresets(true)}
                    className="mt-3 w-full py-2 flex items-center justify-center gap-2 text-sm font-semibold text-gray-500 hover:text-accent transition"
                >
                    <BookOpen className="w-4 h-4" /> Use Saved Meal
                </button>
            </div>

            {/* History */}
            <div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 ml-2">History</h3>
                <div className="bg-white/60 backdrop-blur-lg rounded-[32px] p-2 border border-white/50 min-h-[100px] animate-slide-up">
                    {todaysLogs.length === 0 ? (
                        <div className="text-center py-8 text-gray-400">
                            No magic added for this date yet ✨
                        </div>
                    ) : (
                        todaysLogs.map((log) => (
                            <div key={log.id} className="relative flex justify-between items-center p-4 mb-1 last:mb-0 rounded-2xl bg-white/40 hover:bg-white/80 transition-colors">
                                <div>
                                    <div className="text-xs font-bold text-gray-400 mb-1">
                                        {new Date(log.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </div>
                                    <div className="flex items-baseline gap-2 flex-wrap">
                                        {showCal && <span className="font-bold text-lg text-gray-800">{log.cal} kcal</span>}
                                        {showPro && <span className="text-sm font-bold text-protein">{log.pro}g pro</span>}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 z-10 relative">
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateSavePreset(log);
                                        }}
                                        className="p-3 text-gray-400 hover:text-yellow-500 hover:bg-yellow-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Save to presets"
                                    >
                                        <Bookmark className="w-5 h-5" />
                                    </button>
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateDelete(log.id);
                                        }}
                                        className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Delete entry"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Modals */}
            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)} 
                settings={settings}
                onSave={setSettings} 
            />

            <PresetsModal 
                isOpen={showPresets} 
                onClose={() => setShowPresets(false)} 
                presets={presets}
                onSelect={handleSelectPreset}
                onDelete={handleDeletePreset}
            />

            <SavePresetModal
                isOpen={showSaveModal}
                onClose={() => setShowSaveModal(false)}
                onSave={finalizeSavePreset}
            />

            <ConfirmModal
                isOpen={showConfirmModal}
                onClose={() => setShowConfirmModal(false)}
                onConfirm={confirmDelete}
                title="Delete Entry?"
                message="Are you sure you want to remove this logged meal? This action cannot be undone."
            />

            <CalendarModal
                isOpen={showCalendar}
                onClose={() => setShowCalendar(false)}
                currentDate={currentDate}
                onSelectDate={handleDateSelect}
                history={history}
                goals={settings.goals}
            />
        </div>
    );
}

export default App;

import React, { useState, useEffect } from 'react';
import { X, ChevronLeft, ChevronRight, Star } from './Icons';
import { LogEntry, Goals } from '../types';

interface CalendarModalProps {
    isOpen: boolean;
    onClose: () => void;
    currentDate: Date;
    onSelectDate: (date: Date) => void;
    history: LogEntry[];
    goals: Goals;
}

const CalendarModal: React.FC<CalendarModalProps> = ({ isOpen, onClose, currentDate, onSelectDate, history, goals }) => {
    const [viewDate, setViewDate] = useState(new Date());

    useEffect(() => {
        if (isOpen) {
            setViewDate(new Date(currentDate));
        }
    }, [isOpen, currentDate]);

    if (!isOpen) return null;

    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();

    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const days = [];
    // Padding
    for (let i = 0; i < firstDayOfMonth; i++) {
        days.push(null);
    }
    // Days
    for (let i = 1; i <= daysInMonth; i++) {
        days.push(i);
    }

    const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

    const changeMonth = (offset: number) => {
        const newDate = new Date(viewDate);
        newDate.setMonth(newDate.getMonth() + offset);
        setViewDate(newDate);
    };

    // Calculate daily status
    // Map: Day Number -> { cal: number, pro: number }
    const dailyData = new Map<number, { cal: number, pro: number }>();

    history.forEach(h => {
        const [entryYear, entryMonth, entryDay] = h.date.split('-').map(Number);
        // Ensure we only process this month's data
        if (entryYear === year && (entryMonth - 1) === month) {
            const existing = dailyData.get(entryDay) || { cal: 0, pro: 0 };
            dailyData.set(entryDay, {
                cal: existing.cal + h.cal,
                pro: existing.pro + h.pro
            });
        }
    });

    const getStatus = (day: number) => {
        const data = dailyData.get(day);
        if (!data) return 'none';

        // Logic Refinement:
        // Perfect (Star): Under/Equal Cal Limit AND At/Over Protein Goal
        // Goal Met (Indigo): At/Over Protein Goal (regardless of Cal Limit)
        // Logged (Gray): Logged data but missed Protein Goal

        const metCal = data.cal > 0 && data.cal <= (goals.cal || 2000);
        const metPro = data.pro >= (goals.pro || 150);

        if (metCal && metPro) return 'star'; 
        if (metPro) return 'good';           
        return 'logged';
    };

    return (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
             <div className="bg-white/90 backdrop-blur-xl p-6 rounded-3xl shadow-2xl w-full max-w-sm animate-pop-in">
                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-gray-800">Select Date</h3>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                {/* Calendar Controls */}
                <div className="flex justify-between items-center mb-6 px-2">
                    <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 rounded-full transition">
                        <ChevronLeft className="w-5 h-5 text-gray-600" />
                    </button>
                    <span className="font-bold text-lg text-gray-800 w-32 text-center">
                        {monthNames[month]} {year}
                    </span>
                    <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 rounded-full transition">
                        <ChevronRight className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                {/* Weekdays */}
                <div className="grid grid-cols-7 mb-2 text-center">
                    {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(d => (
                        <div key={d} className="text-xs font-bold text-gray-400 py-2">
                            {d}
                        </div>
                    ))}
                </div>

                {/* Days Grid */}
                <div className="grid grid-cols-7 gap-1 mb-6">
                    {days.map((d, i) => {
                        if (d === null) return <div key={`empty-${i}`} />;

                        const isSelected = d === currentDate.getDate() && month === currentDate.getMonth() && year === currentDate.getFullYear();
                        const isToday = d === new Date().getDate() && month === new Date().getMonth() && year === new Date().getFullYear();
                        const status = getStatus(d as number);

                        return (
                            <button
                                key={d}
                                onClick={() => {
                                    const selected = new Date(year, month, d as number);
                                    onSelectDate(selected);
                                }}
                                className={`
                                    relative h-10 w-10 mx-auto rounded-full flex items-center justify-center text-sm font-medium transition-all
                                    ${isSelected ? 'bg-black text-white shadow-lg scale-105' : 'text-gray-700 hover:bg-gray-100'}
                                    ${isToday && !isSelected ? 'border-2 border-accent text-accent' : ''}
                                `}
                            >
                                {d}

                                {/* Indicators */}
                                {!isSelected && status === 'star' && (
                                    <div className="absolute -bottom-1 text-yellow-500 drop-shadow-sm">
                                        <Star className="w-3 h-3" filled={true} />
                                    </div>
                                )}
                                {!isSelected && status === 'good' && (
                                    <div className="absolute bottom-1.5 w-1.5 h-1.5 bg-indigo-500 rounded-full shadow-sm"></div>
                                )}
                                {!isSelected && status === 'logged' && (
                                    <div className="absolute bottom-1.5 w-1.5 h-1.5 bg-gray-300 rounded-full"></div>
                                )}
                            </button>
                        );
                    })}
                </div>

                {/* Legend */}
                <div className="flex justify-center gap-4 text-[10px] text-gray-500 font-medium">
                     <div className="flex items-center gap-1">
                        <Star className="w-3 h-3 text-yellow-500" filled={true} />
                        <span>Perfect</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                        <span>Protein Met</span>
                    </div>
                     <div className="flex items-center gap-1">
                        <div className="w-1.5 h-1.5 bg-gray-300 rounded-full"></div>
                        <span>Logged</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CalendarModal;

import React, { useEffect, useRef } from 'react';

const Confetti = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Resize canvas to full screen
        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        window.addEventListener('resize', resize);
        resize();

        // Theme colors: Accent (Orange), Protein (Purple), Gold, Blue
        const colors = ['#FF7E5F', '#764BA2', '#FBBF24', '#667EEA'];

        const particles: any[] = [];
        const particleCount = 150;

        for (let i = 0; i < particleCount; i++) {
            particles.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height - canvas.height,
                vx: Math.random() * 4 - 2,     // Horizontal velocity
                vy: Math.random() * 5 + 3,     // Vertical velocity (falling speed)
                color: colors[Math.floor(Math.random() * colors.length)],
                size: Math.random() * 8 + 4,
                rotation: Math.random() * 360,
                rotationSpeed: Math.random() * 10 - 5,
                shape: Math.random() > 0.5 ? 'rect' : 'circle' 
            });
        }

        let animationId: number;

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            particles.forEach((p) => {
                p.y += p.vy;
                p.x += p.vx;
                p.rotation += p.rotationSpeed;

                // Reset if off screen
                if (p.y > canvas.height) {
                    p.y = -20;
                    p.x = Math.random() * canvas.width;
                    p.vy = Math.random() * 5 + 3; // Randomize speed again
                }

                ctx.save();
                ctx.translate(p.x, p.y);
                ctx.rotate((p.rotation * Math.PI) / 180);
                ctx.fillStyle = p.color;

                if (p.shape === 'rect') {
                    ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
                } else {
                    ctx.beginPath();
                    ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
                    ctx.fill();
                }

                ctx.restore();
            });

            animationId = requestAnimationFrame(animate);
        };

        animate();

        return () => {
            cancelAnimationFrame(animationId);
            window.removeEventListener('resize', resize);
        };
    }, []);

    return (
        <canvas 
            ref={canvasRef} 
            className="fixed inset-0 pointer-events-none z-[100] animate-fade-in"
        />
    );
};

export default Confetti;

import React, { useState, useEffect, useMemo } from 'react';
import { LogEntry, Settings, Preset } from './types';
import { ChevronLeft, ChevronRight, SettingsIcon, BookOpen, Trash2, Bookmark } from './components/Icons';
import ProgressRing from './components/ProgressRing';
import SettingsModal from './components/SettingsModal';
import PresetsModal from './components/PresetsModal';
import SavePresetModal from './components/SavePresetModal';
import ConfirmModal from './components/ConfirmModal';
import CalendarModal from './components/CalendarModal';
import Confetti from './components/Confetti';

// FIX: Use local time construction to prevent timezone shifting (UTC vs Local)
const formatDateKey = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

const getDisplayDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
};

const DEFAULT_SETTINGS: Settings = { 
    goals: { cal: 2000, pro: 150 },
    mode: 'both' 
};

function App() {
    // --- State ---
    const [history, setHistory] = useState<LogEntry[]>([]);
    const [settings, setSettings] = useState<Settings>(DEFAULT_SETTINGS);
    const [presets, setPresets] = useState<Preset[]>([]);
    const [currentDate, setCurrentDate] = useState<Date>(new Date());

    // Inputs
    const [inputCal, setInputCal] = useState('');
    const [inputPro, setInputPro] = useState('');

    // Modals & UI State
    const [showSettings, setShowSettings] = useState(false);
    const [showPresets, setShowPresets] = useState(false);
    const [showSaveModal, setShowSaveModal] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [showCalendar, setShowCalendar] = useState(false);
    const [showConfetti, setShowConfetti] = useState(false);

    // Staging Data
    const [entryToSave, setEntryToSave] = useState<LogEntry | null>(null);
    const [entryToDelete, setEntryToDelete] = useState<string | null>(null);

    // --- Persistence ---
    useEffect(() => {
        const stored = localStorage.getItem('glowTracker');
        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                if (parsed.history) setHistory(parsed.history);
                if (parsed.presets) setPresets(parsed.presets);
                if (parsed.settings) {
                    setSettings(parsed.settings);
                } else if (parsed.goals) {
                    setSettings({ ...DEFAULT_SETTINGS, goals: parsed.goals });
                }
            } catch (e) {
                console.error("Failed to load data", e);
            }
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('glowTracker', JSON.stringify({ 
            history, 
            settings, 
            presets 
        }));
    }, [history, settings, presets]);

    // --- Derived Data ---
    const dateKey = formatDateKey(currentDate);
    // Fix: Ensure "isToday" comparison uses local string generation
    const isToday = dateKey === formatDateKey(new Date());

    const todaysLogs = useMemo(() => {
        return history.filter(h => h.date === dateKey).sort((a, b) => b.ts - a.ts);
    }, [history, dateKey]);

    const stats = useMemo(() => {
        return todaysLogs.reduce((acc, log) => ({
            cal: acc.cal + log.cal,
            pro: acc.pro + log.pro
        }), { cal: 0, pro: 0 });
    }, [todaysLogs]);

    const weeklyAvg = useMemo(() => {
        const oneWeekAgo = new Date();
        oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
        const weekKey = oneWeekAgo.getTime();

        const relevant = history.filter(h => h.ts > weekKey);
        const daysMap: Record<string, {cal: number, pro: number}> = {};

        relevant.forEach(h => {
            if (!daysMap[h.date]) daysMap[h.date] = { cal: 0, pro: 0 };
            daysMap[h.date].cal += h.cal;
            daysMap[h.date].pro += h.pro;
        });

        const daysLogged = Object.keys(daysMap).length || 1;
        const total = Object.values(daysMap).reduce((acc, d) => ({ cal: acc.cal + d.cal, pro: acc.pro + d.pro }), { cal: 0, pro: 0 });

        return {
            cal: Math.round(total.cal / daysLogged),
            pro: Math.round(total.pro / daysLogged)
        };
    }, [history]);

    // --- Actions ---
    const handleAdd = (c?: number, p?: number, label?: string) => {
        const cVal = c !== undefined ? c : parseInt(inputCal);
        const pVal = p !== undefined ? p : parseInt(inputPro);

        const cleanCal = isNaN(cVal) ? 0 : cVal;
        const cleanPro = isNaN(pVal) ? 0 : pVal;

        if (cleanCal === 0 && cleanPro === 0) return;

        // Check for celebration (Only triggers if adding data to TODAY)
        if (isToday) {
            const currentPro = stats.pro;
            const goalPro = settings.goals.pro;
            // Celebration Trigger: previously under goal, now met/exceeded
            if (currentPro < goalPro && (currentPro + cleanPro) >= goalPro) {
                setShowConfetti(true);
                setTimeout(() => setShowConfetti(false), 5000);
            }
        }

        const newEntry: LogEntry = {
            id: Date.now().toString() + Math.random().toString(),
            date: dateKey,
            ts: Date.now(),
            cal: cleanCal,
            pro: cleanPro,
            label: label
        };

        setHistory(prev => [...prev, newEntry]);
        setInputCal('');
        setInputPro('');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const initiateDelete = (id: string) => {
        setEntryToDelete(id);
        setShowConfirmModal(true);
    };

    const confirmDelete = () => {
        if (entryToDelete) {
            setHistory(prev => prev.filter(h => h.id !== entryToDelete));
            setEntryToDelete(null);
        }
    };

    const initiateSavePreset = (entry: LogEntry) => {
        setEntryToSave(entry);
        setShowSaveModal(true);
    };

    const finalizeSavePreset = (name: string) => {
        if (entryToSave && name) {
            // 1. Add to presets list
            const newPreset: Preset = {
                id: Date.now().toString(),
                label: name,
                cal: entryToSave.cal,
                pro: entryToSave.pro
            };
            setPresets(prev => [...prev, newPreset]);

            // 2. Update the existing history entry with the new name
            setHistory(prev => prev.map(item => 
                item.id === entryToSave.id ? { ...item, label: name } : item
            ));

            setShowSaveModal(false);
            setEntryToSave(null);
        }
    };

    const handleDeletePreset = (id: string) => {
        setPresets(prev => prev.filter(p => p.id !== id));
    };

    const handleSelectPreset = (preset: Preset) => {
        handleAdd(preset.cal, preset.pro, preset.label);
        setShowPresets(false);
    };

    const changeDate = (days: number) => {
        const next = new Date(currentDate);
        next.setDate(currentDate.getDate() + days);
        setCurrentDate(next);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setShowCalendar(false);
    };

    // --- Render Helpers ---
    const showCal = settings.mode === 'both' || settings.mode === 'cal';
    const showPro = settings.mode === 'both' || settings.mode === 'pro';

    return (
        <div className="min-h-screen pb-10 max-w-[480px] mx-auto px-5 pt-safe-top">
            {showConfetti && <Confetti />}

            {/* Header */}
            <header className="flex justify-between items-center py-6">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-gray-800">Hey! ✨</h1>
                    <div className="flex items-center gap-2 mt-1 text-gray-500 text-sm font-medium">
                        <button onClick={() => changeDate(-1)} className="p-1 hover:bg-gray-200 rounded-full transition">
                            <ChevronLeft className="w-4 h-4" />
                        </button>

                        <button 
                            onClick={() => setShowCalendar(true)}
                            className="px-2 py-1 -mx-2 hover:bg-white/50 rounded-lg transition active:scale-95 flex items-center gap-1"
                        >
                            <span>{isToday ? "Today, " : ""}{getDisplayDate(currentDate)}</span>
                        </button>

                        <button 
                            onClick={() => changeDate(1)} 
                            disabled={isToday}
                            className={`p-1 rounded-full transition ${isToday ? 'opacity-30 cursor-not-allowed' : 'hover:bg-gray-200'}`}
                        >
                            <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                </div>
                <button 
                    onClick={() => setShowSettings(true)} 
                    className="p-3 bg-white/50 rounded-2xl hover:bg-white transition shadow-sm active:scale-95"
                >
                    <SettingsIcon className="text-gray-700 w-6 h-6" />
                </button>
            </header>

            {/* Weekly Stats */}
            <div className="bg-white/60 backdrop-blur-xl rounded-[32px] p-6 shadow-sm border border-white/50 mb-6 animate-pop-in">
                <div className="inline-block px-4 py-2 rounded-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white text-xs font-bold mb-4 shadow-md shadow-indigo-500/20">
                    WEEKLY AVERAGE
                </div>
                <div className={`flex justify-around items-center ${!showCal || !showPro ? 'justify-center' : ''}`}>
                    {showCal && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-gray-800">{weeklyAvg.cal}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Kcal</span>
                        </div>
                    )}
                    {showCal && showPro && <div className="w-px h-10 bg-gray-200"></div>}
                    {showPro && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-protein">{weeklyAvg.pro}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Protein</span>
                        </div>
                    )}
                </div>
            </div>

            {/* Rings & Input */}
            <div className="bg-white/80 backdrop-blur-xl rounded-[32px] p-6 shadow-lg shadow-gray-200/50 mb-8 border border-white animate-pop-in [animation-delay:100ms]">
                <div className={`grid gap-4 mb-8 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1 justify-items-center'}`}>
                    {showCal && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.cal / (settings.goals.cal || 1)} 
                            type="cal"
                            label={stats.cal.toString()} 
                            subLabel="kcal"
                        />
                    )}
                    {showPro && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.pro / (settings.goals.pro || 1)} 
                            type="pro"
                            label={stats.pro.toString()} 
                            subLabel="protein"
                        />
                    )}
                </div>

                <div className="flex gap-3">
                    <div className={`flex-1 grid gap-3 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1'}`}>
                        {showCal && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Cal" 
                                value={inputCal}
                                onChange={(e) => setInputCal(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-accent outline-none transition-all"
                            />
                        )}
                        {showPro && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Pro" 
                                value={inputPro}
                                onChange={(e) => setInputPro(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-protein outline-none transition-all"
                            />
                        )}
                    </div>
                    <div className="flex flex-col gap-2">
                        <button 
                            onClick={() => handleAdd()} 
                            className="h-full bg-gray-900 text-white rounded-2xl px-5 font-bold text-2xl active:scale-95 transition-transform shadow-lg shadow-gray-900/20"
                        >
                            +
                        </button>
                    </div>
                </div>
                 <button 
                    onClick={() => setShowPresets(true)}
                    className="mt-3 w-full py-2 flex items-center justify-center gap-2 text-sm font-semibold text-gray-500 hover:text-accent transition"
                >
                    <BookOpen className="w-4 h-4" /> Use Saved Meal
                </button>
            </div>

            {/* History */}
            <div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 ml-2">History</h3>
                <div className="bg-white/60 backdrop-blur-lg rounded-[32px] p-2 border border-white/50 min-h-[100px] animate-slide-up">
                    {todaysLogs.length === 0 ? (
                        <div className="text-center py-8 text-gray-400">
                            No magic added for this date yet ✨
                        </div>
                    ) : (
                        todaysLogs.map((log) => (
                            <div key={log.id} className="relative flex justify-between items-center p-4 mb-1 last:mb-0 rounded-2xl bg-white/40 hover:bg-white/80 transition-colors">
                                <div>
                                    <div className="text-xs font-bold text-gray-400 mb-1 flex items-center gap-2">
                                        <span>{new Date(log.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                        {log.label && (
                                            <>
                                                <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                                <span className="text-gray-700 font-semibold truncate max-w-[120px]">{log.label}</span>
                                            </>
                                        )}
                                    </div>
                                    <div className="flex items-baseline gap-2 flex-wrap">
                                        {showCal && <span className="font-bold text-lg text-gray-800">{log.cal} kcal</span>}
                                        {showPro && <span className="text-sm font-bold text-protein">{log.pro}g pro</span>}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 z-10 relative">
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateSavePreset(log);
                                        }}
                                        className="p-3 text-gray-400 hover:text-yellow-500 hover:bg-yellow-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Save to presets"
                                    >
                                        <Bookmark className="w-5 h-5" filled={!!log.label} />
                                    </button>
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateDelete(log.id);
                                        }}
                                        className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Delete entry"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Modals */}
            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)} 
                settings={settings}
                onSave={setSettings} 
            />

            <PresetsModal 
                isOpen={showPresets} 
                onClose={() => setShowPresets(false)} 
                presets={presets}
                onSelect={handleSelectPreset}
                onDelete={handleDeletePreset}
            />

            <SavePresetModal
                isOpen={showSaveModal}
                onClose={() => setShowSaveModal(false)}
                onSave={finalizeSavePreset}
            />

            <ConfirmModal
                isOpen={showConfirmModal}
                onClose={() => setShowConfirmModal(false)}
                onConfirm={confirmDelete}
                title="Delete Entry?"
                message="Are you sure you want to remove this logged meal? This action cannot be undone."
            />

            <CalendarModal
                isOpen={showCalendar}
                onClose={() => setShowCalendar(false)}
                currentDate={currentDate}
                onSelectDate={handleDateSelect}
                history={history}
                goals={settings.goals}
            />
        </div>
    );
}

export default App;

