                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Modals */}
            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)} 
                settings={settings}
                onSave={setSettings} 
            />

            <PresetsModal 
                isOpen={showPresets} 
