import React, { useEffect, useRef, useState } from 'react';

interface ConfettiProps {
    onComplete?: () => void;
}

const Confetti: React.FC<ConfettiProps> = ({ onComplete }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [isFading, setIsFading] = useState(false);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Resize canvas to full screen
        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        window.addEventListener('resize', resize);
        resize();

        // Theme colors: Accent (Orange), Protein (Purple), Gold, Blue
        const colors = ['#FF7E5F', '#764BA2', '#FBBF24', '#667EEA'];

        const particles: any[] = [];
        const particleCount = 150;

        for (let i = 0; i < particleCount; i++) {
            particles.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height - canvas.height,
                vx: Math.random() * 4 - 2,     // Horizontal velocity
                vy: Math.random() * 5 + 3,     // Vertical velocity (falling speed)
                color: colors[Math.floor(Math.random() * colors.length)],
                size: Math.random() * 8 + 4,
                rotation: Math.random() * 360,
                rotationSpeed: Math.random() * 10 - 5,
                shape: Math.random() > 0.5 ? 'rect' : 'circle' 
            });
        }

        let animationId: number;

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            particles.forEach((p) => {
                p.y += p.vy;
                p.x += p.vx;
                p.rotation += p.rotationSpeed;

                // Reset if off screen
                if (p.y > canvas.height) {
                    p.y = -20;
                    p.x = Math.random() * canvas.width;
                    p.vy = Math.random() * 5 + 3; // Randomize speed again
                }

                ctx.save();
                ctx.translate(p.x, p.y);
                ctx.rotate((p.rotation * Math.PI) / 180);
                ctx.fillStyle = p.color;

                if (p.shape === 'rect') {
                    ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
                } else {
                    ctx.beginPath();
                    ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
                    ctx.fill();
                }

                ctx.restore();
            });

            animationId = requestAnimationFrame(animate);
        };

        animate();

        // Timeline for fading out
        const fadeTimer = setTimeout(() => {
            setIsFading(true);
        }, 3000); // Start fading after 3 seconds

        const completeTimer = setTimeout(() => {
            if (onComplete) onComplete();
        }, 4000); // Unmount after 4 seconds (1s fade)

        return () => {
            cancelAnimationFrame(animationId);
            window.removeEventListener('resize', resize);
            clearTimeout(fadeTimer);
            clearTimeout(completeTimer);
        };
    }, [onComplete]);

    return (
        <canvas 
            ref={canvasRef} 
            className={`fixed inset-0 pointer-events-none z-[100] transition-opacity duration-1000 ${isFading ? 'opacity-0' : 'animate-fade-in'}`}
        />
    );
};

