import React, { useState, useEffect } from 'react';
import { Preset, TrackingMode } from '../types';
import { X, Flame } from './Icons';

interface SuggestionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onLogSuggestions: (items: Preset[]) => void;
    remainingCal: number;
    remainingPro: number;
    presets: Preset[];
    mode: TrackingMode;
}

const SuggestionModal: React.FC<SuggestionModalProps> = ({ 
    isOpen, 
    onClose, 
    onLogSuggestions, 
    remainingCal, 
    remainingPro, 
    presets,
    mode 
}) => {
    const [suggestions, setSuggestions] = useState<Preset[]>([]);
    const [totals, setTotals] = useState({ cal: 0, pro: 0 });
    const [isLoading, setIsLoading] = useState(false);

    // Algorithm Configuration
    const CAL_TOLERANCE = 100; // +/- 100 kcal
    const PRO_TOLERANCE_LOWER = 5; // -5g
    const PRO_TOLERANCE_UPPER = 10; // +10g

    const generate = () => {
        setIsLoading(true);

        // Use timeout to allow UI to render loading state
        setTimeout(() => {
            if (presets.length === 0) {
                setSuggestions([]);
                setIsLoading(false);
                return;
            }

            let bestCombo: Preset[] = [];
            let bestScore = Infinity; // Lower is better

            // We will run a randomized greedy search
            const ITERATIONS = 2000;

            for (let i = 0; i < ITERATIONS; i++) {
                let currentCombo: Preset[] = [];
                let currentCal = 0;
                let currentPro = 0;

                // Shuffle presets to get variety
                const shuffled = [...presets].sort(() => Math.random() - 0.5);

                // SORTING LOGIC:
                // User wants to prioritize foods with "worse" protein/calorie ratio first (real food)
                // rather than just filling up on protein shakes.
                // Ratio = Cal / Pro. 
                // High Ratio (e.g. 500cal/20g = 25) -> Pasta/Burger.
                // Low Ratio (e.g. 100cal/20g = 5) -> Protein Shake/Chicken Breast.
                // We add some fuzziness so it's not purely deterministic every time.
                const weightedPresets = shuffled.sort((a, b) => {
                    const ratioA = (a.cal / (a.pro || 1)) * (Math.random() * 0.4 + 0.8);
                    const ratioB = (b.cal / (b.pro || 1)) * (Math.random() * 0.4 + 0.8);
                    // Sort Descending (Worse/Higher ratio first)
                    return ratioB - ratioA;
                });

                for (const item of weightedPresets) {
                    // Check if adding this item breaks the UPPER limits significantly
                    // We allow going slightly over, but try to stay close
                    if (currentCal + item.cal <= remainingCal + CAL_TOLERANCE && 
                        currentPro + item.pro <= remainingPro + PRO_TOLERANCE_UPPER) {

                        currentCombo.push(item);
                        currentCal += item.cal;
                        currentPro += item.pro;
                    }
                }

                // Scoring the result
                const calDiff = Math.abs(remainingCal - currentCal);
                const proDiff = Math.abs(remainingPro - currentPro);

                let score = 0;

                if (mode === 'pro') {
                    // Prioritize hitting protein, cals matter less
                    score = proDiff * 2 + calDiff * 0.5;
                } else if (mode === 'cal') {
                    // Prioritize hitting cals, pro matters less
                    score = calDiff * 2 + proDiff * 0.5;
                } else {
                    // Both matter
                    score = calDiff + proDiff * 2; // Weight protein slightly higher to avoid under-eating protein
                }

                // Penalize empty combos
                if (currentCombo.length === 0) score = Infinity;

                if (score < bestScore) {
                    bestScore = score;
                    bestCombo = currentCombo;
                }
            }

            setSuggestions(bestCombo);
            setTotals(bestCombo.reduce((acc, item) => ({ cal: acc.cal + item.cal, pro: acc.pro + item.pro }), { cal: 0, pro: 0 }));
            setIsLoading(false);
        }, 50);
    };

    useEffect(() => {
        if (isOpen) {
            generate();
        }
    }, [isOpen]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
            <div className="bg-white/95 backdrop-blur-xl p-6 rounded-[32px] shadow-2xl w-full max-w-sm animate-pop-in max-h-[85vh] flex flex-col">
                <div className="flex justify-between items-center mb-6 shrink-0">
                    <div className="flex items-center gap-2">
                        <div className="bg-yellow-100 p-2 rounded-xl text-yellow-600">
                            <Flame className="w-5 h-5" filled />
                        </div>
                        <h3 className="text-xl font-bold text-gray-800">Smart Suggestion</h3>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                <div className="mb-4 shrink-0">
                    <div className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-2">Remaining Goal</div>
                    <div className="flex items-center gap-4">
                        <div className="font-black text-2xl text-gray-800">{remainingCal > 0 ? remainingCal : 0} <span className="text-sm text-gray-400 font-bold">kcal</span></div>
                        <div className="w-px h-6 bg-gray-200"></div>
                        <div className="font-black text-2xl text-protein">{remainingPro > 0 ? remainingPro : 0} <span className="text-sm text-gray-400 font-bold">g</span></div>
                    </div>
                </div>

                {/* Suggestions List */}
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2 mb-4">
                    {isLoading ? (
                        <div className="flex justify-center py-10">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-accent"></div>
                        </div>
                    ) : suggestions.length > 0 ? (
                        suggestions.map((item, idx) => (
                            <div key={`${item.id}-${idx}`} className="bg-white border border-gray-100 p-4 rounded-2xl flex justify-between items-center shadow-sm">
                                <div>
                                    <div className="font-bold text-gray-800">{item.label}</div>
                                    <div className="text-xs text-gray-500">{item.cal} kcal • {item.pro}g pro</div>
                                </div>
                                <div className="h-6 w-6 rounded-full bg-green-100 text-green-600 flex items-center justify-center text-xs font-bold">
                                    ✓
                                </div>
                            </div>
                        ))
                    ) : (
                        <div className="text-center py-8 text-gray-400 text-sm">
                            Couldn't find a good combination from your saved meals to fit this gap. Try creating more presets!
                        </div>
                    )}
                </div>

                {/* Result Summary */}
                <div className="bg-gray-50 rounded-2xl p-4 mb-4 shrink-0 border border-gray-100">
                    <div className="flex justify-between items-center mb-1">
                        <span className="text-xs font-bold text-gray-500">SUGGESTED TOTAL</span>
                        <button onClick={generate} className="text-xs font-bold text-accent hover:underline">Regenerate</button>
                    </div>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-xl font-black ${Math.abs(remainingCal - totals.cal) > 100 ? 'text-red-500' : 'text-gray-800'}`}>
                            {totals.cal}
                        </span>
                        <span className="text-xs font-bold text-gray-400">kcal</span>

                        <span className="mx-2 text-gray-300">|</span>

                        <span className={`text-xl font-black ${Math.abs(remainingPro - totals.pro) > 10 ? 'text-red-500' : 'text-protein'}`}>
                            {totals.pro}
                        </span>
                        <span className="text-xs font-bold text-gray-400">pro</span>
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-3 shrink-0">
                    <button 
                        onClick={onClose}
                        className="py-3 rounded-2xl font-bold text-gray-500 hover:bg-gray-100 transition"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={() => {
                            if (suggestions.length > 0) {
                                onLogSuggestions(suggestions);
                                onClose();
                            }
                        }}
                        disabled={suggestions.length === 0}
                        className={`py-3 rounded-2xl font-bold text-white transition shadow-lg ${suggestions.length > 0 ? 'bg-black active:scale-95' : 'bg-gray-300'}`}
                    >
                        Log All
                    </button>
                </div>
            </div>
        </div>
    );
};

