import React, { useState, useEffect } from 'react';
import { Preset, TrackingMode } from '../types';
import { X, Flame } from './Icons';

interface SuggestionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onLogSuggestions: (items: Preset[]) => void;
    remainingCal: number;
    remainingPro: number;
    presets: Preset[];
    mode: TrackingMode;
}

const SuggestionModal: React.FC<SuggestionModalProps> = ({ 
    isOpen, 
    onClose, 
    onLogSuggestions, 
    remainingCal, 
    remainingPro, 
    presets,
    mode 
}) => {
    const [suggestions, setSuggestions] = useState<Preset[]>([]);
    const [totals, setTotals] = useState({ cal: 0, pro: 0 });
    const [isLoading, setIsLoading] = useState(false);

    // Algorithm Configuration
    const CAL_TOLERANCE = 100; 

    const generate = () => {
        setIsLoading(true);

        // Use timeout to allow UI to render loading state
        setTimeout(() => {
            if (presets.length === 0) {
                setSuggestions([]);
                setIsLoading(false);
                return;
            }

            let bestCombo: Preset[] = [];
            let bestScore = Infinity; // Lower is better

            // Weights Configuration
            // User feedback: "Protein goal should be prioritized when protein is active."
            // We set weights to heavily punish missing protein targets.
            const wPro = mode === 'cal' ? 0.5 : 50; // Huge weight on Protein
            const wCal = mode === 'pro' ? 0.5 : 5;  // Moderate weight on Calories
            const wVariety = 150; // Penalty score for adding a duplicate item (encourages variety)

            const ITERATIONS = 1000;

            for (let i = 0; i < ITERATIONS; i++) {
                let currentCombo: Preset[] = [];
                let currentCal = 0;
                let currentPro = 0;
                const counts: Record<string, number> = {};

                let stalled = false;

                // Construct a solution step-by-step
                // We limit to 20 items max to prevent infinite loops in edge cases
                while (!stalled && currentCombo.length < 20) {
                    const needCal = remainingCal - currentCal;
                    const needPro = remainingPro - currentPro;

                    // CHECK STOPPING CONDITIONS

                    // 1. Protein Goal:
                    // If mode is protein/both, we want to be AT or ABOVE target.
                    // So we are "good" if needPro <= 0. 
                    // However, we allow a tiny bit under (e.g. 2g) to be acceptable to stop searching.
                    const isProMet = mode === 'cal' ? true : (needPro <= 2);

                    // 2. Calorie Goal:
                    // We want to be close to 0 difference.
                    const isCalMet = Math.abs(needCal) < (CAL_TOLERANCE / 2);

                    // If goals are met, stop adding items
                    if (isProMet && (mode === 'pro' || isCalMet)) {
                        break;
                    }

                    // Safety break: If we are way over calories (and counting calories), stop.
                    // Allows going over if we prioritize protein, but within reason (e.g. +500)
                    if (needCal < -500) break; 


                    // SCORE CANDIDATES
                    // We look at every preset and see how well it helps us close the CURRENT gap.
                    const candidates = presets.map(p => {
                        const count = counts[p.id] || 0;
                        if (count >= 10) return { p, score: Infinity }; // Max 10x limit

                        // Predict state after adding this item
                        const nextCal = currentCal + p.cal;
                        const nextPro = currentPro + p.pro;

                        const diffCal = Math.abs(remainingCal - nextCal);

                        // Protein Diff Logic:
                        // If we are UNDER target (positive diff), it hurts a lot.
                        // If we are OVER target (negative diff), it hurts very little (bonus even?).
                        // We use a linear penalty for being under.
                        const rawDiffPro = remainingPro - nextPro;
                        const diffProPenalty = rawDiffPro > 0 
                            ? rawDiffPro * 2  // Linear cost for missing protein
                            : Math.abs(rawDiffPro) * 0.1; // Small cost for exceeding protein (efficiency check)

                        let score = (diffCal * wCal) + (diffProPenalty * wPro);

                        // Variety Penalty:
                        // If we already have this item, add a penalty to the score.
                        // This makes unique items "cheaper" to pick than duplicates.
                        score += (count * wVariety);

                        // Random Noise:
                        // Adds variability so we don't pick the same greedy path every iteration.
                        score += (Math.random() * 40); 

                        return { p, score };
                    });

                    // Pick best candidate
                    candidates.sort((a, b) => a.score - b.score);
                    const best = candidates[0];

                    // If the best option is terrible (Infinity), stop
                    if (best.score === Infinity) {
                        stalled = true;
                    } else {
                        // Check if adding this actually moves us further away significantly
                        // (The score handles this mostly, but sometimes we want to stop if the 'best' moves us wildly off)

                        currentCombo.push(best.p);
                        currentCal += best.p.cal;
                        currentPro += best.p.pro;
                        counts[best.p.id] = (counts[best.p.id] || 0) + 1;
                    }
                }

                // EVALUATE FINAL COMBO
                // Once the loop breaks (goals met or stuck), we score the final result.

                const finalCalDiff = Math.abs(remainingCal - currentCal);
                const finalProDiffRaw = remainingPro - currentPro;

                // Final Penalty for missing protein is MASSIVE to ensure we prefer solutions that hit it.
                // If we are short on protein, penalty is squared or very high.
                const finalProPenalty = finalProDiffRaw > 0 ? (finalProDiffRaw * 100) : 0; 

                let finalScore = (finalCalDiff * wCal) + finalProPenalty;

                // Tie-breaker: Prefer fewer items / variety
                const uniqueCount = new Set(currentCombo.map(x => x.id)).size;
                const duplicateCount = currentCombo.length - uniqueCount;
                finalScore += duplicateCount * 5; 

                // Tie-breaker: Prefer getting closer to exact cal match if protein is hit
                if (finalProDiffRaw <= 0) {
                     finalScore += finalCalDiff; 
                }

                if (finalScore < bestScore) {
                    bestScore = finalScore;
                    bestCombo = currentCombo;
                }
            }

            setSuggestions(bestCombo);
            setTotals(bestCombo.reduce((acc, item) => ({ cal: acc.cal + item.cal, pro: acc.pro + item.pro }), { cal: 0, pro: 0 }));
            setIsLoading(false);
        }, 50);
    };

    useEffect(() => {
        if (isOpen) {
            generate();
        }
    }, [isOpen]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
            <div className="bg-white/95 backdrop-blur-xl p-6 rounded-[32px] shadow-2xl w-full max-w-sm animate-pop-in max-h-[85vh] flex flex-col">
                <div className="flex justify-between items-center mb-6 shrink-0">
                    <div className="flex items-center gap-2">
                        <div className="bg-yellow-100 p-2 rounded-xl text-yellow-600">
                            <Flame className="w-5 h-5" filled />
                        </div>
                        <h3 className="text-xl font-bold text-gray-800">Smart Suggestion</h3>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                <div className="mb-4 shrink-0">
                    <div className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-2">Remaining Goal</div>
                    <div className="flex items-center gap-4">
                        <div className="font-black text-2xl text-gray-800">{remainingCal > 0 ? remainingCal : 0} <span className="text-sm text-gray-400 font-bold">kcal</span></div>
                        <div className="w-px h-6 bg-gray-200"></div>
                        <div className="font-black text-2xl text-protein">{remainingPro > 0 ? remainingPro : 0} <span className="text-sm text-gray-400 font-bold">g</span></div>
                    </div>
                </div>

                {/* Suggestions List */}
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2 mb-4">
                    {isLoading ? (
                        <div className="flex justify-center py-10">
