import React, { useState } from 'react';
import { Settings, TrackingMode, LogEntry, Preset, AppData } from '../types';
import { X, Calculator, Download, Upload } from './Icons';
import CalculatorModal from './CalculatorModal';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    settings: Settings;
    onSave: (newSettings: Settings) => void;
    history?: LogEntry[];
    presets?: Preset[];
    onImportData?: (data: AppData, mode: 'full' | 'presets_only') => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ 
    isOpen, 
    onClose, 
    settings, 
    onSave,
    history = [],
    presets = [],
    onImportData
}) => {
    const [cal, setCal] = useState(settings.goals.cal.toString());
    const [pro, setPro] = useState(settings.goals.pro.toString());
    const [mode, setMode] = useState<TrackingMode>(settings.mode);
    const [showCalculator, setShowCalculator] = useState(false);

    if (!isOpen) return null;

    const handleSave = () => {
        onSave({
            goals: {
                cal: parseInt(cal) || 2000,
                pro: parseInt(pro) || 150
            },
            mode: mode
        });
        onClose();
    };

    const handleAutoApply = (c: number, p: number) => {
        setCal(c.toString());
        setPro(p.toString());
        setShowCalculator(false);
    };

    const handleExport = () => {
        const data: AppData = {
            history,
            presets,
            settings: {
                ...settings,
                goals: { cal: parseInt(cal) || 2000, pro: parseInt(pro) || 150 },
                mode: mode
            }
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `simplycal_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);

                // Validate content
                const hasHistory = Array.isArray(json.history) && json.history.length > 0;
                const hasPresets = Array.isArray(json.presets) && json.presets.length > 0;
                const hasSettings = !!json.settings;

                if (!hasHistory && !hasPresets && !hasSettings) {
                    alert("Invalid file: No recognizable data found.");
                    return;
                }

                if (onImportData) {
                    let importMode: 'full' | 'presets_only' | null = null;

                    // Logic flow for user decision
                    if (hasHistory && hasPresets) {
                        if (window.confirm(`Found ${json.history.length} history entries and ${json.presets.length} saved meals.\n\nClick OK to merge EVERYTHING (History + Meals).\nClick Cancel to choose other options.`)) {
                            importMode = 'full';
                        } else {
                            // User cancelled full merge, ask about presets only
                            if (window.confirm("Would you like to import JUST the Saved Meals (presets)?\nThis will keep your current history intact.")) {
                                importMode = 'presets_only';
                            }
                        }
                    } else if (hasHistory) {
                         if (window.confirm("Restore history and settings from this backup?")) {
                             importMode = 'full';
                         }
                    } else if (hasPresets) {
                         if (window.confirm(`Import ${json.presets.length} saved meals?`)) {
                             importMode = 'presets_only';
                         }
                    }

                    if (importMode) {
                        onImportData(json as AppData, importMode);
                        onClose();
                    }
                }
            } catch (err: any) {
                console.error(err);
                alert("Failed to import: " + (err.message || "Unknown error"));
            }
            // Reset input so same file can be selected again if needed
            e.target.value = '';
        };
        reader.readAsText(file);
    };

    return (
        <>
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-fade-in p-4">
                <div className="bg-white/90 backdrop-blur-xl p-6 rounded-3xl shadow-2xl w-full max-w-sm animate-pop-in max-h-[90vh] overflow-y-auto no-scrollbar">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-gray-800">Settings</h3>
                        <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                            <X className="w-5 h-5 text-gray-600" />
                        </button>
                    </div>

                    <div className="space-y-6">
                        {/* Mode Selection */}
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-2">Tracking Mode</label>
                            <div className="grid grid-cols-3 gap-2 bg-gray-100 p-1 rounded-xl">
                                {(['cal', 'both', 'pro'] as TrackingMode[]).map((m) => (
                                    <button
                                        key={m}
                                        onClick={() => setMode(m)}
                                        className={`py-2 px-3 rounded-lg text-sm font-bold transition-all ${
                                            mode === m 
                                            ? 'bg-white text-gray-900 shadow-sm' 
                                            : 'text-gray-400 hover:text-gray-600'
                                        }`}
                                    >
                                        {m === 'both' ? 'Both' : m === 'cal' ? 'Kcal' : 'Pro'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Goal Inputs */}
                        <div className="space-y-4">
                            <div className="flex justify-between items-end">
                                <label className="block text-sm font-bold text-gray-800">Daily Goals</label>
                                <button 
                                    onClick={() => setShowCalculator(true)}
                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-xs font-bold hover:bg-indigo-100 transition"
                                >
                                    <Calculator className="w-3 h-3" />
                                    <span>Auto Fill</span>
                                </button>
                            </div>

                            {(mode === 'cal' || mode === 'both') && (
                                <div>
                                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">CALORIES</label>
                                    <input 
                                        type="number" 
                                        value={cal} 
                                        onChange={(e) => setCal(e.target.value)}
                                        className="w-full p-4 bg-gray-50 rounded-2xl border-none focus:ring-2 focus:ring-accent outline-none text-lg transition-all font-bold text-gray-800"
                                        placeholder="2000"
                                    />
                                </div>
                            )}
                            {(mode === 'pro' || mode === 'both') && (
                                <div>
                                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">PROTEIN (g)</label>
                                    <input 
                                        type="number" 
                                        value={pro} 
                                        onChange={(e) => setPro(e.target.value)}
                                        className="w-full p-4 bg-gray-50 rounded-2xl border-none focus:ring-2 focus:ring-protein outline-none text-lg transition-all font-bold text-gray-800"
                                        placeholder="150"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Data Management Section */}
                        <div className="border-t border-gray-100 pt-6">
                            <label className="block text-sm font-bold text-gray-800 mb-3">Data Management</label>
                            <div className="grid grid-cols-2 gap-3">
                                <button 
                                    onClick={handleExport}
                                    className="flex flex-col items-center justify-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition border border-transparent hover:border-gray-200"
                                >
                                    <div className="mb-2 p-2 bg-white rounded-full shadow-sm text-gray-700">
                                        <Download className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-600">Export</span>
                                </button>

                                <label className="flex flex-col items-center justify-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition border border-transparent hover:border-gray-200 cursor-pointer">
                                    <input 
                                        type="file" 
                                        accept=".json" 
                                        className="hidden" 
                                        onChange={handleImportFile}
                                    />
                                    <div className="mb-2 p-2 bg-white rounded-full shadow-sm text-gray-700">
                                        <Upload className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-600">Import</span>
                                </label>
                            </div>
                        </div>
                    </div>

                    <button 
                        onClick={handleSave}
                        className="mt-8 w-full bg-black text-white py-4 rounded-2xl font-bold text-lg active:scale-95 transition-transform shadow-xl shadow-gray-200"
                    >
                        Save Changes
                    </button>
                </div>
            </div>

            <CalculatorModal 
                isOpen={showCalculator} 
                onClose={() => setShowCalculator(false)} 
                onApply={handleAutoApply} 
            />
        </>
    );
};

export default SettingsModal;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { LogEntry, Settings, Preset, AppData } from './types';
import { ChevronLeft, ChevronRight, SettingsIcon, BookOpen, Trash2, Bookmark, Calculator } from './components/Icons';
import ProgressRing from './components/ProgressRing';
import SettingsModal from './components/SettingsModal';
import PresetsModal from './components/PresetsModal';
import SavePresetModal from './components/SavePresetModal';
import NameModal from './components/NameModal';
import ConfirmModal from './components/ConfirmModal';
import CalendarModal from './components/CalendarModal';
import BackupReminderModal from './components/BackupReminderModal';
import Confetti from './components/Confetti';
import InstallPrompt from './components/InstallPrompt';
import FoodCalculatorModal from './components/FoodCalculatorModal';
import SuggestionModal from './components/SuggestionModal';

// FIX: Use local time construction to prevent timezone shifting (UTC vs Local)
const formatDateKey = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

const getDisplayDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
};

const DEFAULT_SETTINGS: Settings = { 
    goals: { cal: 2000, pro: 150 },
    mode: 'both',
    name: ''
};

function App() {
    // --- State ---
    const [history, setHistory] = useState<LogEntry[]>([]);
    const [settings, setSettings] = useState<Settings>(DEFAULT_SETTINGS);
    const [presets, setPresets] = useState<Preset[]>([]);
    const [currentDate, setCurrentDate] = useState<Date>(new Date());
    const [isDataLoaded, setIsDataLoaded] = useState(false);

    // Inputs
    const [inputCal, setInputCal] = useState('');
    const [inputPro, setInputPro] = useState('');

    // UI Toggle State
    const [statsPeriod, setStatsPeriod] = useState<'weekly' | 'monthly'>('weekly');
    const [showStatusText, setShowStatusText] = useState(false);
    const statusTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    // Modals & UI State
    const [showSettings, setShowSettings] = useState(false);
    const [showPresets, setShowPresets] = useState(false);
    const [showSaveModal, setShowSaveModal] = useState(false);
    const [showNameModal, setShowNameModal] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [showCalendar, setShowCalendar] = useState(false);
    const [showBackupReminder, setShowBackupReminder] = useState(false);
    const [showFoodCalculator, setShowFoodCalculator] = useState(false);
    const [showSuggestion, setShowSuggestion] = useState(false);
    const [showConfetti, setShowConfetti] = useState(false);

    // Logic State
    const [hasCelebrated, setHasCelebrated] = useState(false);

    // Staging Data
    const [entryToSave, setEntryToSave] = useState<LogEntry | null>(null);
    const [entryToDelete, setEntryToDelete] = useState<string | null>(null);

    // --- Persistence ---
    useEffect(() => {
        const stored = localStorage.getItem('glowTracker');
        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                if (parsed.history) setHistory(parsed.history);
                if (parsed.presets) setPresets(parsed.presets);
                if (parsed.settings) {
                    setSettings(parsed.settings);
                } else if (parsed.goals) {
                    setSettings({ ...DEFAULT_SETTINGS, goals: parsed.goals });
                }
            } catch (e) {
                console.error("Failed to load data", e);
            }
        }
        setIsDataLoaded(true);
    }, []);

    useEffect(() => {
        if (!isDataLoaded) return;
        localStorage.setItem('glowTracker', JSON.stringify({ 
            history, 
            settings, 
            presets 
        }));
    }, [history, settings, presets, isDataLoaded]);

    // --- Backup Reminder Logic ---
    useEffect(() => {
        if (!isDataLoaded || history.length === 0) return;

        const checkBackup = () => {
            const now = new Date();

            // 1. Check if it's the last day of the month
            const tomorrow = new Date(now);
            tomorrow.setDate(now.getDate() + 1);
            // If tomorrow is the 1st, then today is the last day
            if (tomorrow.getDate() !== 1) return;

            // 2. Check if already shown this month
            const currentMonthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
            const lastShown = localStorage.getItem('simplycal_backup_reminder_seen');
            if (lastShown === currentMonthKey) return;

            // 3. Check days since start (Minimum 20 days)
            const sortedHistory = [...history].sort((a, b) => a.date.localeCompare(b.date));
            const firstEntry = sortedHistory[0];

            // Parse date manually to ensure local time comparison
            const [y, m, d] = firstEntry.date.split('-').map(Number);
            const startDate = new Date(y, m - 1, d);

            // Calculate difference in days
            const diffTime = Math.abs(now.getTime() - startDate.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays >= 20) {
                setShowBackupReminder(true);
            }
        };

        checkBackup();
    }, [isDataLoaded, history.length]);

    // --- Check if goal met on load to prevent duplicate celebration ---
    useEffect(() => {
        const dateKey = formatDateKey(new Date());
        const todaysLogs = history.filter(h => h.date === dateKey);
        const totalPro = todaysLogs.reduce((sum, item) => sum + item.pro, 0);

        if (totalPro >= settings.goals.pro && settings.goals.pro > 0) {
            setHasCelebrated(true);
        }
    }, [history.length]); // Simple check on mount/load

    // --- Derived Data ---
    const dateKey = formatDateKey(currentDate);
    const isToday = dateKey === formatDateKey(new Date());

    const todaysLogs = useMemo(() => {
        return history.filter(h => h.date === dateKey).sort((a, b) => b.ts - a.ts);
    }, [history, dateKey]);

    const stats = useMemo(() => {
        return todaysLogs.reduce((acc, log) => ({
            cal: acc.cal + log.cal,
            pro: acc.pro + log.pro
        }), { cal: 0, pro: 0 });
    }, [todaysLogs]);

    const periodStats = useMemo(() => {
        let startStr: string;
        let endStr: string;

        // Clone current date to avoid mutation issues
        const curr = new Date(currentDate);

        if (statsPeriod === 'weekly') {
            // Monday - Sunday logic
            const day = curr.getDay(); // 0 is Sunday
            const dayAdjusted = day === 0 ? 7 : day; // Convert to 1 (Mon) - 7 (Sun)
            const diff = curr.getDate() - dayAdjusted + 1; // Calculate Monday

            const startOfWeek = new Date(curr);
            startOfWeek.setDate(diff);

            const endOfWeek = new Date(startOfWeek);
            endOfWeek.setDate(startOfWeek.getDate() + 6); // End on Sunday

            startStr = formatDateKey(startOfWeek);
            endStr = formatDateKey(endOfWeek);
        } else {
            // Get Month (Calendar Month)
            const startOfMonth = new Date(curr.getFullYear(), curr.getMonth(), 1);
            const endOfMonth = new Date(curr.getFullYear(), curr.getMonth() + 1, 0); // Last day of month

            startStr = formatDateKey(startOfMonth);
            endStr = formatDateKey(endOfMonth);
        }

        // Filter history based on range strings (inclusive)
        const relevantLogs = history.filter(h => h.date >= startStr && h.date <= endStr);

        // Group by day to calculate average daily intake
        const daysMap: Record<string, {cal: number, pro: number}> = {};

        relevantLogs.forEach(h => {
            if (!daysMap[h.date]) daysMap[h.date] = { cal: 0, pro: 0 };
            daysMap[h.date].cal += h.cal;
            daysMap[h.date].pro += h.pro;
        });

        const daysLogged = Object.keys(daysMap).length || 1;
        const total = Object.values(daysMap).reduce((acc, d) => ({ cal: acc.cal + d.cal, pro: acc.pro + d.pro }), { cal: 0, pro: 0 });

        return {
            cal: Math.round(total.cal / daysLogged),
            pro: Math.round(total.pro / daysLogged)
        };
    }, [history, statsPeriod, currentDate]); // Added currentDate dependency

    const getStatusMessage = (avgCal: number, goalCal: number) => {
        const diff = avgCal - goalCal; // Positive means OVER goal, Negative means UNDER goal

        // "200 cals under goal" -> diff <= -200
        if (diff <= -200) return "Eat some more?";

        // "199 under to 100 over" -> -199 <= diff <= 100
        if (diff > -200 && diff <= 100) return "On track ❤️";

        // "101 over til 300 over" -> 101 <= diff <= 300
        if (diff > 100 && diff <= 300) return "Slowly losing weight";

        // "301 over to 600 over" -> 301 <= diff <= 600
        if (diff > 300 && diff <= 600) return "Maintaining weight";

        // "over 601" -> diff >= 601
        if (diff > 600) return "Gaining weight";

        return "";
    };

    const statusMessage = useMemo(() => {
        if (!settings.goals.cal) return "";
        return getStatusMessage(periodStats.cal, settings.goals.cal);
    }, [periodStats.cal, settings.goals.cal]);


    // --- Actions ---
    const handleToggleStats = () => {
        setStatsPeriod(prev => prev === 'weekly' ? 'monthly' : 'weekly');

        // Reset and start timer for text visibility
        setShowStatusText(true);
        if (statusTimerRef.current) {
            clearTimeout(statusTimerRef.current);
        }
        statusTimerRef.current = setTimeout(() => {
            setShowStatusText(false);
        }, 10000); // 10 seconds
    };

    // Use callback for confetti to prevent re-creation on render, which triggers useEffect cleanup/restart
    const handleConfettiComplete = useCallback(() => {
        setShowConfetti(false);
    }, []);

    const handleAdd = (c?: number, p?: number, label?: string) => {
        const cVal = c !== undefined ? c : parseInt(inputCal);
        const pVal = p !== undefined ? p : parseInt(inputPro);

        const cleanCal = isNaN(cVal) ? 0 : cVal;
        const cleanPro = isNaN(pVal) ? 0 : pVal;

        if (cleanCal === 0 && cleanPro === 0) return;

        // 1. Check for Celebration (Goal Met Today)
        if (isToday) {
            const currentPro = stats.pro;
            const goalPro = settings.goals.pro;
            if (!hasCelebrated && currentPro < goalPro && (currentPro + cleanPro) >= goalPro) {
                setShowConfetti(true);
                setHasCelebrated(true);
            }
        }

        const newEntry: LogEntry = {
            id: Date.now().toString() + Math.random().toString(),
            date: dateKey,
            ts: Date.now(),
            cal: cleanCal,
            pro: cleanPro,
            label: label
        };

        setHistory(prev => [...prev, newEntry]);
        setInputCal('');
        setInputPro('');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleLogSuggestions = (items: Preset[]) => {
        // Log all suggested items
        const newEntries: LogEntry[] = items.map(item => ({
            id: Date.now().toString() + Math.random().toString(),
            date: dateKey,
            ts: Date.now(),
            cal: item.cal,
            pro: item.pro,
            label: item.label
        }));

        setHistory(prev => [...prev, ...newEntries]);

        // Check celebration for suggestions
        if (isToday) {
            const addedPro = items.reduce((sum, item) => sum + item.pro, 0);
            const currentPro = stats.pro;
            const goalPro = settings.goals.pro;
            if (!hasCelebrated && currentPro < goalPro && (currentPro + addedPro) >= goalPro) {
                setShowConfetti(true);
                setHasCelebrated(true);
            }
        }
    };

    const initiateDelete = (id: string) => {
        setEntryToDelete(id);
        setShowConfirmModal(true);
    };

    const confirmDelete = () => {
        if (entryToDelete) {
            setHistory(prev => prev.filter(h => h.id !== entryToDelete));
            setEntryToDelete(null);
        }
    };

    const initiateSavePreset = (entry: LogEntry) => {
        setEntryToSave(entry);
        setShowSaveModal(true);
    };

    const finalizeSavePreset = (name: string) => {
        if (entryToSave && name) {
            // 1. Add to presets list
            const newPreset: Preset = {
                id: Date.now().toString(),
                label: name,
                cal: entryToSave.cal,
                pro: entryToSave.pro
            };
            setPresets(prev => [...prev, newPreset]);

            // 2. Update the existing history entry with the new name
            setHistory(prev => prev.map(item => 
                item.id === entryToSave.id ? { ...item, label: name } : item
            ));

            setShowSaveModal(false);
            setEntryToSave(null);
        }
    };

    const handleDeletePreset = (id: string) => {
        setPresets(prev => prev.filter(p => p.id !== id));
    };

    const handleSelectPreset = (preset: Preset) => {
        handleAdd(preset.cal, preset.pro, preset.label);
        setShowPresets(false);
    };

    const handleApplyFoodCalculation = (c: number, p: number) => {
        // Log immediately instead of putting in input fields
        handleAdd(c, p);
    };

    const changeDate = (days: number) => {
        const next = new Date(currentDate);
        next.setDate(currentDate.getDate() + days);
        setCurrentDate(next);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setShowCalendar(false);
    };

    const handleNameSave = (name: string) => {
        setSettings(prev => ({ ...prev, name }));
    };

    const handleImportData = (data: AppData, mode: 'full' | 'presets_only' = 'full') => {
        // Safe check for data integrity
        if (!data || typeof data !== 'object') {
            throw new Error("Invalid data format");
        }

        // 1. Presets (Always Merge logic)
        // We always import presets because that's usually the user's intent when "importing foods"
        const incomingPresets = Array.isArray(data.presets) ? data.presets : [];
        const existingPresetsMap = new Map(presets.map(p => [p.id, p]));
        // Add or overwrite presets based on ID
        incomingPresets.forEach(p => existingPresetsMap.set(p.id, p));
        const newPresets = Array.from(existingPresetsMap.values());

        let newHistory = history;
        let newSettings = settings;

        // 2. Full Restore Logic (Only if requested)
        if (mode === 'full') {
            const incomingHistory = Array.isArray(data.history) ? data.history : [];
            const existingHistoryMap = new Map(history.map(h => [h.id, h]));
            incomingHistory.forEach(h => existingHistoryMap.set(h.id, h));
            newHistory = Array.from(existingHistoryMap.values());

            // Merge Settings
            if (data.settings && typeof data.settings === 'object') {
                 newSettings = {
                    ...settings,
                    ...data.settings,
                    goals: {
                        ...settings.goals,
                        ...(data.settings.goals || {})
                    }
                };
            }
        }

        setHistory(newHistory);
        setPresets(newPresets);
        setSettings(newSettings);

        // Force save merged data immediately to local storage
        localStorage.setItem('glowTracker', JSON.stringify({
            history: newHistory,
            presets: newPresets,
            settings: newSettings
        }));

        // Success Feedback
        if (mode === 'full') {
            alert("Full backup restored successfully!");
        } else {
            alert(`Imported ${incomingPresets.length} meal presets successfully!`);
        }

        // Re-evaluate celebration state based on new data if relevant
        try {
            const todays = newHistory.filter(h => h.date === formatDateKey(new Date()));
            const totalPro = todays.reduce((sum, item) => sum + item.pro, 0);

            if (newSettings.goals && newSettings.goals.pro > 0) {
                if (totalPro >= newSettings.goals.pro) {
                    setHasCelebrated(true);
                }
            }
        } catch (e) {
            console.warn("Celebration check failed during import", e);
        }
    };

    // Helper for export to reuse logic
    const exportData = () => {
        const data: AppData = {
            history,
            presets,
            settings
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `simplycal_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const markBackupSeen = () => {
        const now = new Date();
        const currentMonthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
        localStorage.setItem('simplycal_backup_reminder_seen', currentMonthKey);
        setShowBackupReminder(false);
    };

    const handleBackupConfirm = () => {
        exportData();
        markBackupSeen();
    };

    const handleRingClick = () => {
        // Removed date check to allow testing/planning on other days
        const remCal = settings.goals.cal - stats.cal;
        const remPro = settings.goals.pro - stats.pro;

        // Lowered threshold to ensure it opens even for small amounts
        if (remCal > 0 || remPro > 0) {
            setShowSuggestion(true);
        }
    };

    // --- Render Helpers ---
    const showCal = settings.mode === 'both' || settings.mode === 'cal';
    const showPro = settings.mode === 'both' || settings.mode === 'pro';

    // Calculation for text positioning based on mode
    // If 'both' or 'pro' is active, we target the protein column location (~75% across for 'both', 50% across for 'pro')
    const textPositionClass = settings.mode === 'both' 
        ? 'left-[77%] -translate-x-1/2' 
        : 'left-1/2 -translate-x-1/2';

    return (
        <div className="min-h-screen pb-10 max-w-[480px] mx-auto px-5 pt-14">
            {showConfetti && <Confetti onComplete={handleConfettiComplete} />}
            <InstallPrompt />

            {/* Header */}
            <header className="flex justify-between items-center py-6">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-gray-800 flex items-center gap-2">
                        Hey! {settings.name} 
                        <button 
                            onClick={() => setShowNameModal(true)}
                            className="hover:scale-110 transition-transform active:scale-90"
                        >
                            ✨
                        </button>
                    </h1>
                    <div className="flex items-center gap-2 mt-1 text-gray-500 text-sm font-medium">
                        <button onClick={() => changeDate(-1)} className="p-1 hover:bg-gray-200 rounded-full transition">
                            <ChevronLeft className="w-4 h-4" />
                        </button>

                        <button 
                            onClick={() => setShowCalendar(true)}
                            className="px-2 py-1 -mx-2 hover:bg-white/50 rounded-lg transition active:scale-95 flex items-center gap-1"
                        >
                            <span>{isToday ? "Today, " : ""}{getDisplayDate(currentDate)}</span>
                        </button>

                        <button 
                            onClick={() => changeDate(1)} 
                            disabled={isToday}
                            className={`p-1 rounded-full transition ${isToday ? 'opacity-30 cursor-not-allowed' : 'hover:bg-gray-200'}`}
                        >
                            <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                </div>
                <button 
                    onClick={() => setShowSettings(true)} 
                    className="p-3 bg-white/50 rounded-2xl hover:bg-white transition shadow-sm active:scale-95"
                >
                    <SettingsIcon className="text-gray-700 w-6 h-6" />
                </button>
            </header>

            {/* Stats Card */}
            <div className="bg-white/60 backdrop-blur-xl rounded-[32px] p-6 shadow-sm border border-white/50 mb-6 animate-pop-in relative">
                <div className="flex items-center justify-between mb-4 relative min-h-[32px]">
                    <button 
                        onClick={handleToggleStats}
                        className="px-4 py-2 rounded-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white text-xs font-bold shadow-md shadow-indigo-500/20 hover:opacity-90 transition-opacity uppercase tracking-wide z-10"
                    >
                        {statsPeriod} AVERAGE
                    </button>

                    {/* Status Text - Centered over Protein (or center of card if single mode) */}
                    {statusMessage && (
                        <span 
                            className={`text-xs font-bold text-gray-500 transition-opacity duration-1000 absolute ${textPositionClass} top-1/2 -translate-y-1/2 whitespace-nowrap ${showStatusText ? 'opacity-100' : 'opacity-0'}`}
                        >
                            {statusMessage}
                        </span>
                    )}
                </div>

                <div className={`flex justify-around items-center ${!showCal || !showPro ? 'justify-center' : ''}`}>
                    {showCal && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-gray-800">{periodStats.cal}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Kcal</span>
                        </div>
                    )}
                    {showCal && showPro && <div className="w-px h-10 bg-gray-200"></div>}
                    {showPro && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-protein">{periodStats.pro}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Protein</span>
                        </div>
                    )}
                </div>
            </div>

            {/* Rings & Input */}
            <div className="bg-white/80 backdrop-blur-xl rounded-[32px] p-6 shadow-lg shadow-gray-200/50 mb-8 border border-white animate-pop-in [animation-delay:100ms]">
                <h2 className="text-center text-gray-400 text-sm font-bold uppercase tracking-widest mb-6">
                    {isToday ? "Today" : getDisplayDate(currentDate)}
                </h2>
                <div className={`grid gap-4 mb-8 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1 justify-items-center'}`}>
                    {showCal && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.cal / (settings.goals.cal || 1)} 
                            type="cal"
                            label={stats.cal.toString()} 
                            subLabel="kcal"
                            onClick={handleRingClick}
                        />
                    )}
                    {showPro && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.pro / (settings.goals.pro || 1)} 
                            type="pro"
                            label={stats.pro.toString()} 
                            subLabel="protein"
                            onClick={handleRingClick}
                        />
                    )}
                </div>

                <div className="flex gap-3">
                    <div className={`flex-1 grid gap-3 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1'}`}>
                        {showCal && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Cal" 
                                value={inputCal}
                                onChange={(e) => setInputCal(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-accent outline-none transition-all"
                            />
                        )}
                        {showPro && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Pro" 
                                value={inputPro}
                                onChange={(e) => setInputPro(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-protein outline-none transition-all"
                            />
                        )}
                    </div>
                    <div className="flex flex-col gap-2">
                        <button 
                            onClick={() => handleAdd()} 
                            className="h-full bg-gray-900 text-white rounded-2xl px-5 font-bold text-2xl active:scale-95 transition-transform shadow-lg shadow-gray-900/20"
                        >
                            +
                        </button>
                    </div>
                </div>

                {/* Secondary Actions Grid */}
                <div className="mt-3 flex gap-3">
                     <button 
                        onClick={() => setShowPresets(true)}
                        className="flex-1 py-3 px-2 flex items-center justify-center gap-2 text-sm font-semibold text-gray-500 hover:text-accent hover:bg-white/50 rounded-2xl transition"
                    >
                        <BookOpen className="w-4 h-4" /> Use Saved Meal
                    </button>
                    <button 
                        onClick={() => setShowFoodCalculator(true)}
                        className="flex-1 py-3 px-2 flex items-center justify-center gap-2 text-sm font-semibold text-gray-500 hover:text-accent hover:bg-white/50 rounded-2xl transition"
                    >
                        <Calculator className="w-4 h-4" /> Calculate
                    </button>
                </div>
            </div>

            {/* History */}
            <div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 ml-2">History</h3>
                <div className="bg-white/60 backdrop-blur-lg rounded-[32px] p-2 border border-white/50 min-h-[100px] animate-slide-up">
                    {todaysLogs.length === 0 ? (
                        <div className="text-center py-8 text-gray-400">
                            No magic added for this date yet ✨
                        </div>
                    ) : (
                        todaysLogs.map((log) => (
                            <div key={log.id} className="relative flex justify-between items-center p-4 mb-1 last:mb-0 rounded-2xl bg-white/40 hover:bg-white/80 transition-colors">
                                <div>
                                    <div className="text-xs font-bold text-gray-400 mb-1 flex items-center gap-2">
                                        <span>{new Date(log.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                        {log.label && (
                                            <>
                                                <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                                <span className="text-gray-700 font-semibold truncate max-w-[120px]">{log.label}</span>
                                            </>
                                        )}
                                    </div>
                                    <div className="flex items-baseline gap-2 flex-wrap">
                                        {showCal && <span className="font-bold text-lg text-gray-800">{log.cal} kcal</span>}
                                        {showPro && <span className="text-sm font-bold text-protein">{log.pro}g pro</span>}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 z-10 relative">
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateSavePreset(log);
                                        }}
                                        className="p-3 text-gray-400 hover:text-yellow-500 hover:bg-yellow-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Save to presets"
                                    >
                                        <Bookmark className="w-5 h-5" filled={!!log.label} />
                                    </button>
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateDelete(log.id);
                                        }}
                                        className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Delete entry"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Footer */}
            <div className="text-center py-8 text-xs text-gray-400 font-medium">
                Project by <a href="https://x.com/DiemetriX" target="_blank" rel="noopener noreferrer" className="hover:text-accent transition-colors">Thomas Davis</a>
            </div>

            {/* Modals */}
            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)} 
                settings={settings}
                onSave={setSettings}
                history={history}
                presets={presets}
                onImportData={handleImportData}
            />

            <PresetsModal 
                isOpen={showPresets} 
                onClose={() => setShowPresets(false)} 
                presets={presets}
                onSelect={handleSelectPreset}
                onDelete={handleDeletePreset}
            />

            <SavePresetModal
                isOpen={showSaveModal}
                onClose={() => setShowSaveModal(false)}
                onSave={finalizeSavePreset}
            />

            <NameModal 
                isOpen={showNameModal}
                onClose={() => setShowNameModal(false)}
                currentName={settings.name || ''}
                onSave={handleNameSave}
            />

            <ConfirmModal
                isOpen={showConfirmModal}
                onClose={() => setShowConfirmModal(false)}
                onConfirm={confirmDelete}
                title="Delete Entry?"
                message="Are you sure you want to remove this logged meal? This action cannot be undone."
            />

            <BackupReminderModal
                isOpen={showBackupReminder}
                onClose={markBackupSeen}
                onConfirm={handleBackupConfirm}
            />

            <CalendarModal
                isOpen={showCalendar}
                onClose={() => setShowCalendar(false)}
                currentDate={currentDate}
                onSelectDate={handleDateSelect}
                history={history}
                goals={settings.goals}
            />

            <FoodCalculatorModal 
                isOpen={showFoodCalculator}
                onClose={() => setShowFoodCalculator(false)}
                mode={settings.mode}
                onApply={handleApplyFoodCalculation}
            />

            <SuggestionModal 
                isOpen={showSuggestion} 
                onClose={() => setShowSuggestion(false)}
                onLogSuggestions={handleLogSuggestions}
                remainingCal={settings.goals.cal - stats.cal}
                remainingPro={settings.goals.pro - stats.pro}
                presets={presets}
                mode={settings.mode}
            />
        </div>
    );
}

export default App;

import React, { useState } from 'react';
import { Settings, TrackingMode, LogEntry, Preset, AppData } from '../types';
import { X, Calculator, Download, Upload } from './Icons';
import CalculatorModal from './CalculatorModal';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    settings: Settings;
    onSave: (newSettings: Settings) => void;
    history?: LogEntry[];
    presets?: Preset[];
    onImportData?: (data: AppData, mode: 'full' | 'presets_only') => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ 
    isOpen, 
    onClose, 
    settings, 
    onSave,
    history = [],
    presets = [],
    onImportData
}) => {
    const [cal, setCal] = useState(settings.goals.cal.toString());
    const [pro, setPro] = useState(settings.goals.pro.toString());
    const [mode, setMode] = useState<TrackingMode>(settings.mode);
    const [showCalculator, setShowCalculator] = useState(false);

    // State for Import Decision UI
    const [importData, setImportData] = useState<{
        data: AppData;
        summary: { history: number; presets: number; hasSettings: boolean };
    } | null>(null);

    if (!isOpen) return null;

    const handleSave = () => {
        onSave({
            goals: {
                cal: parseInt(cal) || 2000,
                pro: parseInt(pro) || 150
            },
            mode: mode
        });
        onClose();
    };

    const handleAutoApply = (c: number, p: number) => {
        setCal(c.toString());
        setPro(p.toString());
        setShowCalculator(false);
    };

    const handleExport = () => {
        const data: AppData = {
            history,
            presets,
            settings: {
                ...settings,
                goals: { cal: parseInt(cal) || 2000, pro: parseInt(pro) || 150 },
                mode: mode
            }
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `simplycal_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);

                // Validate content
                const historyCount = Array.isArray(json.history) ? json.history.length : 0;
                const presetsCount = Array.isArray(json.presets) ? json.presets.length : 0;
                const hasSettings = !!json.settings;

                if (historyCount === 0 && presetsCount === 0 && !hasSettings) {
                    alert("Invalid file: No recognizable data found.");
                    return;
                }

                // Show decision UI
                setImportData({
                    data: json,
                    summary: { history: historyCount, presets: presetsCount, hasSettings }
                });

            } catch (err: any) {
                console.error(err);
                alert("Failed to import: " + (err.message || "Unknown error"));
            }
            // Reset input so same file can be selected again if needed
            e.target.value = '';
        };
        reader.readAsText(file);
    };

    const confirmImport = (importMode: 'full' | 'presets_only') => {
        if (!importData || !onImportData) return;

        try {
            onImportData(importData.data, importMode);
            setImportData(null);
            onClose();
        } catch (e: any) {
            console.error(e);
            alert("Error importing data. Please try again.");
        }
    };

    // If import confirmation is pending, show that UI instead of settings
    if (importData) {
        return (
            <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
                <div className="bg-white/95 backdrop-blur-xl p-6 rounded-3xl shadow-2xl w-full max-w-sm animate-pop-in">
                   <h3 className="text-xl font-bold text-gray-800 mb-2">Import Backup</h3>
                   <p className="text-gray-600 mb-6 text-sm leading-relaxed">
                       File contains <strong className="text-gray-900">{importData.summary.history} history items</strong> and <strong className="text-gray-900">{importData.summary.presets} saved meals</strong>.
                   </p>

                   <div className="space-y-3">
                       {/* Option 1: Full Restore (only if history exists) */}
                       {importData.summary.history > 0 && (
                           <button 
                               onClick={() => confirmImport('full')}
                               className="w-full py-3.5 bg-black text-white rounded-2xl font-bold text-sm hover:scale-[1.02] active:scale-95 transition shadow-lg"
                           >
                               Restore Full Backup
                           </button>
                       )}

                       {/* Option 2: Presets Only (only if presets exist) */}
                       {importData.summary.presets > 0 && (
                           <button 
                               onClick={() => confirmImport('presets_only')}
                               className="w-full py-3.5 bg-indigo-50 text-indigo-600 rounded-2xl font-bold text-sm hover:bg-indigo-100 active:scale-95 transition"
                           >
                               Import {importData.summary.presets} Saved Meals Only
                           </button>
                       )}

                       <button 
                           onClick={() => setImportData(null)}
                           className="w-full py-3 text-gray-500 font-bold text-sm hover:bg-gray-100 rounded-2xl transition"
                       >
                           Cancel
                       </button>
                   </div>
                </div>
            </div>
        );
    }

    return (
        <>
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-fade-in p-4">
                <div className="bg-white/90 backdrop-blur-xl p-6 rounded-3xl shadow-2xl w-full max-w-sm animate-pop-in max-h-[90vh] overflow-y-auto no-scrollbar">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-gray-800">Settings</h3>
                        <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                            <X className="w-5 h-5 text-gray-600" />
                        </button>
                    </div>

                    <div className="space-y-6">
                        {/* Mode Selection */}
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-2">Tracking Mode</label>
                            <div className="grid grid-cols-3 gap-2 bg-gray-100 p-1 rounded-xl">
                                {(['cal', 'both', 'pro'] as TrackingMode[]).map((m) => (
                                    <button
                                        key={m}
                                        onClick={() => setMode(m)}
                                        className={`py-2 px-3 rounded-lg text-sm font-bold transition-all ${
                                            mode === m 
                                            ? 'bg-white text-gray-900 shadow-sm' 
                                            : 'text-gray-400 hover:text-gray-600'
                                        }`}
                                    >
                                        {m === 'both' ? 'Both' : m === 'cal' ? 'Kcal' : 'Pro'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Goal Inputs */}
                        <div className="space-y-4">
                            <div className="flex justify-between items-end">
                                <label className="block text-sm font-bold text-gray-800">Daily Goals</label>
                                <button 
                                    onClick={() => setShowCalculator(true)}
                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-xs font-bold hover:bg-indigo-100 transition"
                                >
                                    <Calculator className="w-3 h-3" />
                                    <span>Auto Fill</span>
                                </button>
                            </div>

                            {(mode === 'cal' || mode === 'both') && (
                                <div>
                                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">CALORIES</label>
                                    <input 
                                        type="number" 
                                        value={cal} 
                                        onChange={(e) => setCal(e.target.value)}
                                        className="w-full p-4 bg-gray-50 rounded-2xl border-none focus:ring-2 focus:ring-accent outline-none text-lg transition-all font-bold text-gray-800"
                                        placeholder="2000"
                                    />
                                </div>
                            )}
                            {(mode === 'pro' || mode === 'both') && (
                                <div>
                                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">PROTEIN (g)</label>
                                    <input 
                                        type="number" 
                                        value={pro} 
                                        onChange={(e) => setPro(e.target.value)}
                                        className="w-full p-4 bg-gray-50 rounded-2xl border-none focus:ring-2 focus:ring-protein outline-none text-lg transition-all font-bold text-gray-800"
                                        placeholder="150"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Data Management Section */}
                        <div className="border-t border-gray-100 pt-6">
                            <label className="block text-sm font-bold text-gray-800 mb-3">Data Management</label>
                            <div className="grid grid-cols-2 gap-3">
                                <button 
                                    onClick={handleExport}
                                    className="flex flex-col items-center justify-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition border border-transparent hover:border-gray-200"
                                >
                                    <div className="mb-2 p-2 bg-white rounded-full shadow-sm text-gray-700">
                                        <Download className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-600">Export</span>
                                </button>

                                <label className="flex flex-col items-center justify-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition border border-transparent hover:border-gray-200 cursor-pointer">
                                    <input 
                                        type="file" 
                                        accept=".json" 
                                        className="hidden" 
                                        onChange={handleImportFile}
                                    />
                                    <div className="mb-2 p-2 bg-white rounded-full shadow-sm text-gray-700">
                                        <Upload className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-600">Import</span>
                                </label>
                            </div>
                        </div>
                    </div>

                    <button 
                        onClick={handleSave}
                        className="mt-8 w-full bg-black text-white py-4 rounded-2xl font-bold text-lg active:scale-95 transition-transform shadow-xl shadow-gray-200"
                    >
                        Save Changes
                    </button>
                </div>
            </div>

            <CalculatorModal 
                isOpen={showCalculator} 
                onClose={() => setShowCalculator(false)} 
                onApply={handleAutoApply} 
            />
        </>
    );
};

export default SettingsModal;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { LogEntry, Settings, Preset, AppData } from './types';
import { ChevronLeft, ChevronRight, SettingsIcon, BookOpen, Trash2, Bookmark, Calculator } from './components/Icons';
import ProgressRing from './components/ProgressRing';
import SettingsModal from './components/SettingsModal';
import PresetsModal from './components/PresetsModal';
import SavePresetModal from './components/SavePresetModal';
import NameModal from './components/NameModal';
import ConfirmModal from './components/ConfirmModal';
import CalendarModal from './components/CalendarModal';
import BackupReminderModal from './components/BackupReminderModal';
import Confetti from './components/Confetti';
import InstallPrompt from './components/InstallPrompt';
import FoodCalculatorModal from './components/FoodCalculatorModal';
import SuggestionModal from './components/SuggestionModal';

// FIX: Use local time construction to prevent timezone shifting (UTC vs Local)
const formatDateKey = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

const getDisplayDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
};

const DEFAULT_SETTINGS: Settings = { 
    goals: { cal: 2000, pro: 150 },
    mode: 'both',
    name: ''
};

function App() {
    // --- State ---
    const [history, setHistory] = useState<LogEntry[]>([]);
    const [settings, setSettings] = useState<Settings>(DEFAULT_SETTINGS);
    const [presets, setPresets] = useState<Preset[]>([]);
    const [currentDate, setCurrentDate] = useState<Date>(new Date());
    const [isDataLoaded, setIsDataLoaded] = useState(false);

    // Inputs
    const [inputCal, setInputCal] = useState('');
    const [inputPro, setInputPro] = useState('');

    // UI Toggle State
    const [statsPeriod, setStatsPeriod] = useState<'weekly' | 'monthly'>('weekly');
    const [showStatusText, setShowStatusText] = useState(false);
    const statusTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    // Modals & UI State
    const [showSettings, setShowSettings] = useState(false);
    const [showPresets, setShowPresets] = useState(false);
    const [showSaveModal, setShowSaveModal] = useState(false);
    const [showNameModal, setShowNameModal] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [showCalendar, setShowCalendar] = useState(false);
    const [showBackupReminder, setShowBackupReminder] = useState(false);
    const [showFoodCalculator, setShowFoodCalculator] = useState(false);
    const [showSuggestion, setShowSuggestion] = useState(false);
    const [showConfetti, setShowConfetti] = useState(false);

    // Logic State
    const [hasCelebrated, setHasCelebrated] = useState(false);

    // Staging Data
    const [entryToSave, setEntryToSave] = useState<LogEntry | null>(null);
    const [entryToDelete, setEntryToDelete] = useState<string | null>(null);

    // --- Persistence ---
    useEffect(() => {
        const stored = localStorage.getItem('glowTracker');
        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                if (parsed.history) setHistory(parsed.history);
                if (parsed.presets) setPresets(parsed.presets);
                if (parsed.settings) {
                    setSettings(parsed.settings);
                } else if (parsed.goals) {
                    setSettings({ ...DEFAULT_SETTINGS, goals: parsed.goals });
                }
            } catch (e) {
                console.error("Failed to load data", e);
            }
        }
        setIsDataLoaded(true);
    }, []);

    useEffect(() => {
        if (!isDataLoaded) return;
        localStorage.setItem('glowTracker', JSON.stringify({ 
            history, 
            settings, 
            presets 
        }));
    }, [history, settings, presets, isDataLoaded]);

    // --- Backup Reminder Logic ---
    useEffect(() => {
        if (!isDataLoaded || history.length === 0) return;

        const checkBackup = () => {
            const now = new Date();

            // 1. Check if it's the last day of the month
            const tomorrow = new Date(now);
            tomorrow.setDate(now.getDate() + 1);
            // If tomorrow is the 1st, then today is the last day
            if (tomorrow.getDate() !== 1) return;

            // 2. Check if already shown this month
            const currentMonthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
            const lastShown = localStorage.getItem('simplycal_backup_reminder_seen');
            if (lastShown === currentMonthKey) return;

            // 3. Check days since start (Minimum 20 days)
            const sortedHistory = [...history].sort((a, b) => a.date.localeCompare(b.date));
            const firstEntry = sortedHistory[0];

            // Parse date manually to ensure local time comparison
            const [y, m, d] = firstEntry.date.split('-').map(Number);
            const startDate = new Date(y, m - 1, d);

            // Calculate difference in days
            const diffTime = Math.abs(now.getTime() - startDate.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays >= 20) {
                setShowBackupReminder(true);
            }
        };

        checkBackup();
    }, [isDataLoaded, history.length]);

    // --- Check if goal met on load to prevent duplicate celebration ---
    useEffect(() => {
        const dateKey = formatDateKey(new Date());
        const todaysLogs = history.filter(h => h.date === dateKey);
        const totalPro = todaysLogs.reduce((sum, item) => sum + item.pro, 0);

        if (totalPro >= settings.goals.pro && settings.goals.pro > 0) {
            setHasCelebrated(true);
        }
    }, [history.length]); // Simple check on mount/load

    // --- Derived Data ---
    const dateKey = formatDateKey(currentDate);
    const isToday = dateKey === formatDateKey(new Date());

    const todaysLogs = useMemo(() => {
        return history.filter(h => h.date === dateKey).sort((a, b) => b.ts - a.ts);
    }, [history, dateKey]);

    const stats = useMemo(() => {
        return todaysLogs.reduce((acc, log) => ({
            cal: acc.cal + log.cal,
            pro: acc.pro + log.pro
        }), { cal: 0, pro: 0 });
    }, [todaysLogs]);

    const periodStats = useMemo(() => {
        let startStr: string;
        let endStr: string;

        // Clone current date to avoid mutation issues
        const curr = new Date(currentDate);

        if (statsPeriod === 'weekly') {
            // Monday - Sunday logic
            const day = curr.getDay(); // 0 is Sunday
            const dayAdjusted = day === 0 ? 7 : day; // Convert to 1 (Mon) - 7 (Sun)
            const diff = curr.getDate() - dayAdjusted + 1; // Calculate Monday

            const startOfWeek = new Date(curr);
            startOfWeek.setDate(diff);

            const endOfWeek = new Date(startOfWeek);
            endOfWeek.setDate(startOfWeek.getDate() + 6); // End on Sunday

            startStr = formatDateKey(startOfWeek);
            endStr = formatDateKey(endOfWeek);
        } else {
            // Get Month (Calendar Month)
            const startOfMonth = new Date(curr.getFullYear(), curr.getMonth(), 1);
            const endOfMonth = new Date(curr.getFullYear(), curr.getMonth() + 1, 0); // Last day of month

            startStr = formatDateKey(startOfMonth);
            endStr = formatDateKey(endOfMonth);
        }

        // Filter history based on range strings (inclusive)
        const relevantLogs = history.filter(h => h.date >= startStr && h.date <= endStr);

        // Group by day to calculate average daily intake
        const daysMap: Record<string, {cal: number, pro: number}> = {};

        relevantLogs.forEach(h => {
            if (!daysMap[h.date]) daysMap[h.date] = { cal: 0, pro: 0 };
            daysMap[h.date].cal += h.cal;
            daysMap[h.date].pro += h.pro;
        });

        const daysLogged = Object.keys(daysMap).length || 1;
        const total = Object.values(daysMap).reduce((acc, d) => ({ cal: acc.cal + d.cal, pro: acc.pro + d.pro }), { cal: 0, pro: 0 });

        return {
            cal: Math.round(total.cal / daysLogged),
            pro: Math.round(total.pro / daysLogged)
        };
    }, [history, statsPeriod, currentDate]); // Added currentDate dependency

    const getStatusMessage = (avgCal: number, goalCal: number) => {
        const diff = avgCal - goalCal; // Positive means OVER goal, Negative means UNDER goal

        // "200 cals under goal" -> diff <= -200
        if (diff <= -200) return "Eat some more?";

        // "199 under to 100 over" -> -199 <= diff <= 100
        if (diff > -200 && diff <= 100) return "On track ❤️";

        // "101 over til 300 over" -> 101 <= diff <= 300
        if (diff > 100 && diff <= 300) return "Slowly losing weight";

        // "301 over to 600 over" -> 301 <= diff <= 600
        if (diff > 300 && diff <= 600) return "Maintaining weight";

        // "over 601" -> diff >= 601
        if (diff > 600) return "Gaining weight";

        return "";
    };

    const statusMessage = useMemo(() => {
        if (!settings.goals.cal) return "";
        return getStatusMessage(periodStats.cal, settings.goals.cal);
    }, [periodStats.cal, settings.goals.cal]);


    // --- Actions ---
    const handleToggleStats = () => {
        setStatsPeriod(prev => prev === 'weekly' ? 'monthly' : 'weekly');

        // Reset and start timer for text visibility
        setShowStatusText(true);
        if (statusTimerRef.current) {
            clearTimeout(statusTimerRef.current);
        }
        statusTimerRef.current = setTimeout(() => {
            setShowStatusText(false);
        }, 10000); // 10 seconds
    };

    // Use callback for confetti to prevent re-creation on render, which triggers useEffect cleanup/restart
    const handleConfettiComplete = useCallback(() => {
        setShowConfetti(false);
    }, []);

    const handleAdd = (c?: number, p?: number, label?: string) => {
        const cVal = c !== undefined ? c : parseInt(inputCal);
        const pVal = p !== undefined ? p : parseInt(inputPro);

        const cleanCal = isNaN(cVal) ? 0 : cVal;
        const cleanPro = isNaN(pVal) ? 0 : pVal;

        if (cleanCal === 0 && cleanPro === 0) return;

        // 1. Check for Celebration (Goal Met Today)
        if (isToday) {
            const currentPro = stats.pro;
            const goalPro = settings.goals.pro;
            if (!hasCelebrated && currentPro < goalPro && (currentPro + cleanPro) >= goalPro) {
                setShowConfetti(true);
                setHasCelebrated(true);
            }
        }

        const newEntry: LogEntry = {
            id: Date.now().toString() + Math.random().toString(),
            date: dateKey,
            ts: Date.now(),
            cal: cleanCal,
            pro: cleanPro,
            label: label
        };

        setHistory(prev => [...prev, newEntry]);
        setInputCal('');
        setInputPro('');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleLogSuggestions = (items: Preset[]) => {
        // Log all suggested items
        const newEntries: LogEntry[] = items.map(item => ({
            id: Date.now().toString() + Math.random().toString(),
            date: dateKey,
            ts: Date.now(),
            cal: item.cal,
            pro: item.pro,
            label: item.label
        }));

        setHistory(prev => [...prev, ...newEntries]);

        // Check celebration for suggestions
        if (isToday) {
            const addedPro = items.reduce((sum, item) => sum + item.pro, 0);
            const currentPro = stats.pro;
            const goalPro = settings.goals.pro;
            if (!hasCelebrated && currentPro < goalPro && (currentPro + addedPro) >= goalPro) {
                setShowConfetti(true);
                setHasCelebrated(true);
            }
        }
    };

    const initiateDelete = (id: string) => {
        setEntryToDelete(id);
        setShowConfirmModal(true);
    };

    const confirmDelete = () => {
        if (entryToDelete) {
            setHistory(prev => prev.filter(h => h.id !== entryToDelete));
            setEntryToDelete(null);
        }
    };

    const initiateSavePreset = (entry: LogEntry) => {
        setEntryToSave(entry);
        setShowSaveModal(true);
    };

    const finalizeSavePreset = (name: string) => {
        if (entryToSave && name) {
            // 1. Add to presets list
            const newPreset: Preset = {
                id: Date.now().toString(),
                label: name,
                cal: entryToSave.cal,
                pro: entryToSave.pro
            };
            setPresets(prev => [...prev, newPreset]);

            // 2. Update the existing history entry with the new name
            setHistory(prev => prev.map(item => 
                item.id === entryToSave.id ? { ...item, label: name } : item
            ));

            setShowSaveModal(false);
            setEntryToSave(null);
        }
    };

    const handleDeletePreset = (id: string) => {
        setPresets(prev => prev.filter(p => p.id !== id));
    };

    const handleSelectPreset = (preset: Preset) => {
        handleAdd(preset.cal, preset.pro, preset.label);
        setShowPresets(false);
    };

    const handleApplyFoodCalculation = (c: number, p: number) => {
        // Log immediately instead of putting in input fields
        handleAdd(c, p);
    };

    const changeDate = (days: number) => {
        const next = new Date(currentDate);
        next.setDate(currentDate.getDate() + days);
        setCurrentDate(next);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setShowCalendar(false);
    };

    const handleNameSave = (name: string) => {
        setSettings(prev => ({ ...prev, name }));
    };

    const handleImportData = (data: AppData, mode: 'full' | 'presets_only' = 'full') => {
        // Safe check for data integrity
        if (!data || typeof data !== 'object') {
            alert("Invalid data format");
            return;
        }

        // 1. Presets (Always Merge logic)
        // We always import presets because that's usually the user's intent when "importing foods"
        const incomingPresets = Array.isArray(data.presets) ? data.presets : [];
        const existingPresetsMap = new Map(presets.map(p => [p.id, p]));

        incomingPresets.forEach(p => {
             // Robustness: Skip completely invalid items
             if (!p || (!p.label && !p.cal && !p.pro)) return;

             // Robustness: Check for missing IDs. 
             // If ID is missing, generate one to prevent map collisions (overwrite 'undefined' key)
             let safeId = p.id;
             if (!safeId || safeId.toString().trim() === '') {
                 safeId = `import-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
             }

             const cleanPreset: Preset = {
                id: safeId,
                label: p.label || 'Unnamed Meal',
                cal: Number(p.cal) || 0,
                pro: Number(p.pro) || 0
            };

            // Add or overwrite (if ID matches)
            existingPresetsMap.set(safeId, cleanPreset);
        });

        const newPresets = Array.from(existingPresetsMap.values());

        let newHistory = history;
        let newSettings = settings;

        // 2. Full Restore Logic (Only if requested)
        if (mode === 'full') {
            const incomingHistory = Array.isArray(data.history) ? data.history : [];
            const existingHistoryMap = new Map(history.map(h => [h.id, h]));

            incomingHistory.forEach(h => {
                if (!h) return;
                // Similar robustness for history
                let safeId = h.id;
                if (!safeId || safeId.toString().trim() === '') {
                    safeId = `hist-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
                }
                existingHistoryMap.set(safeId, { ...h, id: safeId });
            });

            newHistory = Array.from(existingHistoryMap.values());

            // Merge Settings
            if (data.settings && typeof data.settings === 'object') {
                 newSettings = {
                    ...settings,
                    ...data.settings,
                    goals: {
                        ...settings.goals,
                        ...(data.settings.goals || {})
                    }
                };
            }
        }

        setHistory(newHistory);
        setPresets(newPresets);
        setSettings(newSettings);

        // Force save merged data immediately to local storage
        localStorage.setItem('glowTracker', JSON.stringify({
            history: newHistory,
            presets: newPresets,
            settings: newSettings
        }));

        // Success Feedback
        if (mode === 'full') {
            alert(`Full backup restored! (History: ${newHistory.length}, Meals: ${newPresets.length})`);
        } else {
            alert(`Success! You now have ${newPresets.length} saved meals.`);
        }

        // Re-evaluate celebration state based on new data if relevant
        try {
            const todays = newHistory.filter(h => h.date === formatDateKey(new Date()));
            const totalPro = todays.reduce((sum, item) => sum + item.pro, 0);

            if (newSettings.goals && newSettings.goals.pro > 0) {
                if (totalPro >= newSettings.goals.pro) {
                    setHasCelebrated(true);
                }
            }
        } catch (e) {
            console.warn("Celebration check failed during import", e);
        }
    };

    // Helper for export to reuse logic
    const exportData = () => {
        const data: AppData = {
            history,
            presets,
            settings
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `simplycal_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const markBackupSeen = () => {
        const now = new Date();
        const currentMonthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
        localStorage.setItem('simplycal_backup_reminder_seen', currentMonthKey);
        setShowBackupReminder(false);
    };

    const handleBackupConfirm = () => {
        exportData();
        markBackupSeen();
    };

    const handleRingClick = () => {
        // Removed date check to allow testing/planning on other days
        const remCal = settings.goals.cal - stats.cal;
        const remPro = settings.goals.pro - stats.pro;

        // Lowered threshold to ensure it opens even for small amounts
        if (remCal > 0 || remPro > 0) {
            setShowSuggestion(true);
        }
    };

    // --- Render Helpers ---
    const showCal = settings.mode === 'both' || settings.mode === 'cal';
    const showPro = settings.mode === 'both' || settings.mode === 'pro';

    // Calculation for text positioning based on mode
    // If 'both' or 'pro' is active, we target the protein column location (~75% across for 'both', 50% across for 'pro')
    const textPositionClass = settings.mode === 'both' 
        ? 'left-[77%] -translate-x-1/2' 
        : 'left-1/2 -translate-x-1/2';

    return (
        <div className="min-h-screen pb-10 max-w-[480px] mx-auto px-5 pt-14">
            {showConfetti && <Confetti onComplete={handleConfettiComplete} />}
            <InstallPrompt />

            {/* Header */}
            <header className="flex justify-between items-center py-6">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-gray-800 flex items-center gap-2">
                        Hey! {settings.name} 
                        <button 
                            onClick={() => setShowNameModal(true)}
                            className="hover:scale-110 transition-transform active:scale-90"
                        >
                            ✨
                        </button>
                    </h1>
                    <div className="flex items-center gap-2 mt-1 text-gray-500 text-sm font-medium">
                        <button onClick={() => changeDate(-1)} className="p-1 hover:bg-gray-200 rounded-full transition">
                            <ChevronLeft className="w-4 h-4" />
                        </button>

                        <button 
                            onClick={() => setShowCalendar(true)}
                            className="px-2 py-1 -mx-2 hover:bg-white/50 rounded-lg transition active:scale-95 flex items-center gap-1"
                        >
                            <span>{isToday ? "Today, " : ""}{getDisplayDate(currentDate)}</span>
                        </button>

                        <button 
                            onClick={() => changeDate(1)} 
                            disabled={isToday}
                            className={`p-1 rounded-full transition ${isToday ? 'opacity-30 cursor-not-allowed' : 'hover:bg-gray-200'}`}
                        >
                            <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                </div>
                <button 
                    onClick={() => setShowSettings(true)} 
                    className="p-3 bg-white/50 rounded-2xl hover:bg-white transition shadow-sm active:scale-95"
                >
                    <SettingsIcon className="text-gray-700 w-6 h-6" />
                </button>
            </header>

            {/* Stats Card */}
            <div className="bg-white/60 backdrop-blur-xl rounded-[32px] p-6 shadow-sm border border-white/50 mb-6 animate-pop-in relative">
                <div className="flex items-center justify-between mb-4 relative min-h-[32px]">
                    <button 
                        onClick={handleToggleStats}
                        className="px-4 py-2 rounded-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white text-xs font-bold shadow-md shadow-indigo-500/20 hover:opacity-90 transition-opacity uppercase tracking-wide z-10"
                    >
                        {statsPeriod} AVERAGE
                    </button>

                    {/* Status Text - Centered over Protein (or center of card if single mode) */}
                    {statusMessage && (
                        <span 
                            className={`text-xs font-bold text-gray-500 transition-opacity duration-1000 absolute ${textPositionClass} top-1/2 -translate-y-1/2 whitespace-nowrap ${showStatusText ? 'opacity-100' : 'opacity-0'}`}
                        >
                            {statusMessage}
                        </span>
                    )}
                </div>

                <div className={`flex justify-around items-center ${!showCal || !showPro ? 'justify-center' : ''}`}>
                    {showCal && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-gray-800">{periodStats.cal}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Kcal</span>
                        </div>
                    )}
                    {showCal && showPro && <div className="w-px h-10 bg-gray-200"></div>}
                    {showPro && (
                        <div className="text-center min-w-[80px]">
                            <span className="block text-3xl font-black text-protein">{periodStats.pro}</span>
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Protein</span>
                        </div>
                    )}
                </div>
            </div>

            {/* Rings & Input */}
            <div className="bg-white/80 backdrop-blur-xl rounded-[32px] p-6 shadow-lg shadow-gray-200/50 mb-8 border border-white animate-pop-in [animation-delay:100ms]">
                <h2 className="text-center text-gray-400 text-sm font-bold uppercase tracking-widest mb-6">
                    {isToday ? "Today" : getDisplayDate(currentDate)}
                </h2>
                <div className={`grid gap-4 mb-8 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1 justify-items-center'}`}>
                    {showCal && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.cal / (settings.goals.cal || 1)} 
                            type="cal"
                            label={stats.cal.toString()} 
                            subLabel="kcal"
                            onClick={handleRingClick}
                        />
                    )}
                    {showPro && (
                        <ProgressRing 
                            radius={settings.mode === 'both' ? 55 : 70} 
                            stroke={settings.mode === 'both' ? 10 : 12} 
                            progress={stats.pro / (settings.goals.pro || 1)} 
                            type="pro"
                            label={stats.pro.toString()} 
                            subLabel="protein"
                            onClick={handleRingClick}
                        />
                    )}
                </div>

                <div className="flex gap-3">
                    <div className={`flex-1 grid gap-3 ${settings.mode === 'both' ? 'grid-cols-2' : 'grid-cols-1'}`}>
                        {showCal && (
                            <input 
                                type="number" 
                                inputMode="numeric" 
                                placeholder="Cal" 
                                value={inputCal}
                                onChange={(e) => setInputCal(e.target.value)}
                                className="w-full bg-gray-100/50 rounded-2xl px-4 py-4 text-center font-bold text-gray-800 placeholder-gray-400 focus:bg-white focus:ring-2 focus:ring-accent outline-none transition-all"
                            />
                        )}
                        {showPro && (
                            <input 
