                    </div>
                    <div className="flex flex-col gap-2">
                        <button 
                            onClick={() => handleAdd()} 
                            className="h-full bg-gray-900 text-white rounded-2xl px-5 font-bold text-2xl active:scale-95 transition-transform shadow-lg shadow-gray-900/20"
                        >
                            +
                        </button>
                    </div>
                </div>

                {/* Secondary Actions Grid */}
                <div className="mt-3 flex gap-3">
                     <button 
                        onClick={() => setShowPresets(true)}
                        className="flex-1 py-3 px-2 flex items-center justify-center gap-2 text-sm font-semibold text-gray-500 hover:text-accent hover:bg-white/50 rounded-2xl transition"
                    >
                        <BookOpen className="w-4 h-4" /> Use Saved Meal
                    </button>
                    <button 
                        onClick={() => setShowFoodCalculator(true)}
                        className="flex-1 py-3 px-2 flex items-center justify-center gap-2 text-sm font-semibold text-gray-500 hover:text-accent hover:bg-white/50 rounded-2xl transition"
                    >
                        <Calculator className="w-4 h-4" /> Calculate
                    </button>
                </div>
            </div>

            {/* History */}
            <div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 ml-2">History</h3>
                <div className="bg-white/60 backdrop-blur-lg rounded-[32px] p-2 border border-white/50 min-h-[100px] animate-slide-up">
                    {todaysLogs.length === 0 ? (
                        <div className="text-center py-8 text-gray-400">
                            No magic added for this date yet ✨
                        </div>
                    ) : (
                        todaysLogs.map((log) => (
                            <div key={log.id} className="relative flex justify-between items-center p-4 mb-1 last:mb-0 rounded-2xl bg-white/40 hover:bg-white/80 transition-colors">
                                <div>
                                    <div className="text-xs font-bold text-gray-400 mb-1 flex items-center gap-2">
                                        <span>{new Date(log.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                        {log.label && (
                                            <>
                                                <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                                <span className="text-gray-700 font-semibold truncate max-w-[120px]">{log.label}</span>
                                            </>
                                        )}
                                    </div>
                                    <div className="flex items-baseline gap-2 flex-wrap">
                                        {showCal && <span className="font-bold text-lg text-gray-800">{log.cal} kcal</span>}
                                        {showPro && <span className="text-sm font-bold text-protein">{log.pro}g pro</span>}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 z-10 relative">
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateSavePreset(log);
                                        }}
                                        className="p-3 text-gray-400 hover:text-yellow-500 hover:bg-yellow-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Save to presets"
                                    >
                                        <Bookmark className="w-5 h-5" filled={!!log.label} />
                                    </button>
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            initiateDelete(log.id);
                                        }}
                                        className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition active:scale-90 cursor-pointer"
                                        aria-label="Delete entry"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Footer */}
            <div className="text-center py-8 text-xs text-gray-400 font-medium">
                Project by <a href="https://x.com/DiemetriX" target="_blank" rel="noopener noreferrer" className="hover:text-accent transition-colors">Thomas Davis</a>
            </div>

            {/* Modals */}
            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)} 
                settings={settings}
                onSave={setSettings}
                history={history}
                presets={presets}
                onImportData={handleImportData}
            />

            <PresetsModal 
                isOpen={showPresets} 
                onClose={() => setShowPresets(false)} 
                presets={presets}
                onSelect={handleSelectPreset}
                onDelete={handleDeletePreset}
            />

            <SavePresetModal
                isOpen={showSaveModal}
                onClose={() => setShowSaveModal(false)}
                onSave={finalizeSavePreset}
            />

            <NameModal 
                isOpen={showNameModal}
                onClose={() => setShowNameModal(false)}
                currentName={settings.name || ''}
                onSave={handleNameSave}
            />

            <ConfirmModal
                isOpen={showConfirmModal}
                onClose={() => setShowConfirmModal(false)}
                onConfirm={confirmDelete}
                title="Delete Entry?"
                message="Are you sure you want to remove this logged meal? This action cannot be undone."
            />

            <BackupReminderModal
                isOpen={showBackupReminder}
                onClose={markBackupSeen}
                onConfirm={handleBackupConfirm}
            />

            <CalendarModal
                isOpen={showCalendar}
                onClose={() => setShowCalendar(false)}
                currentDate={currentDate}
                onSelectDate={handleDateSelect}
                history={history}
                goals={settings.goals}
            />

            <FoodCalculatorModal 
                isOpen={showFoodCalculator}
                onClose={() => setShowFoodCalculator(false)}
                mode={settings.mode}
                onApply={handleApplyFoodCalculation}
            />

            <SuggestionModal 
                isOpen={showSuggestion} 
                onClose={() => setShowSuggestion(false)}
                onLogSuggestions={handleLogSuggestions}
                remainingCal={settings.goals.cal - stats.cal}
                remainingPro={settings.goals.pro - stats.pro}
                presets={presets}
                mode={settings.mode}
            />
        </div>
    );
}

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Preset, TrackingMode } from '../types';
import { X, Flame } from './Icons';

interface SuggestionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onLogSuggestions: (items: Preset[]) => void;
    remainingCal: number;
    remainingPro: number;
    presets: Preset[];
    mode: TrackingMode;
}

interface SuggestionItem {
    item: Preset;
    selected: boolean;
    uniqueKey: string;
}

const SuggestionModal: React.FC<SuggestionModalProps> = ({ 
    isOpen, 
    onClose, 
    onLogSuggestions, 
    remainingCal, 
    remainingPro, 
    presets,
    mode 
}) => {
    const [suggestions, setSuggestions] = useState<SuggestionItem[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    // Track the signature of the currently displayed suggestion to avoid repeating it immediately
    const lastSignatureRef = useRef<string>('');

    // Derived totals based on SELECTED items
    const totals = useMemo(() => {
        return suggestions
            .filter(s => s.selected)
            .reduce((acc, s) => ({ 
                cal: acc.cal + s.item.cal, 
                pro: acc.pro + s.item.pro 
            }), { cal: 0, pro: 0 });
    }, [suggestions]);

    // Heuristic Configuration
    const CAL_TOLERANCE_LOWER = 50;
    const CAL_TOLERANCE_UPPER = 50;
    const MAX_OVERAGE_HARD = 300;

    // Penalties
    const PENALTY_PER_CAL_OVER = 10;
    const PENALTY_PER_CAL_OVER_SQ = 0.05;
    const PENALTY_MISSED_PRO = 30;
    const PENALTY_EXCESS_PRO = 3; // Penalty per gram of excess protein
    const PENALTY_EXCESS_PRO_HEAVY = 8; // Penalty for massive overshoots
    const PENALTY_DUPLICATE_2 = 300; 
    const PENALTY_DUPLICATE_3_PLUS = 5000;
    const PENALTY_SAME_AS_LAST = 10000;

    const generate = () => {
        setIsLoading(true);

        setTimeout(() => {
            if (presets.length === 0) {
                setSuggestions([]);
                setIsLoading(false);
                return;
            }

            // --- PRE-PROCESSING ---
            // Create a pool with efficiency pre-calculated
            const pool = presets.map(p => ({
                ...p,
                efficiency: p.pro / (Math.max(1, p.cal)) // Protein per 1 calorie
            }));

            let bestCombo: Preset[] = [];
            let bestScore = Infinity;

            const ITERATIONS = 5000; 

            for (let i = 0; i < ITERATIONS; i++) {
                const currentCombo: Preset[] = [];
                let currentCal = 0;
                let currentPro = 0;
                const counts: Record<string, number> = {};

                let attempts = 0;

                // Build a combo
                while (attempts < 30 && currentCombo.length < 15) {
                    attempts++;

                    const needCal = remainingCal - currentCal;
                    const needPro = remainingPro - currentPro;

                    // Stop conditions
                    if (mode !== 'cal' && needPro <= 0 && currentCal >= (remainingCal - CAL_TOLERANCE_LOWER)) break;
                    if (mode !== 'pro' && Math.abs(needCal) <= CAL_TOLERANCE_UPPER) break;
                    if (currentCal > remainingCal + MAX_OVERAGE_HARD) break;

                    // Random Candidate
                    let candidate = pool[Math.floor(Math.random() * pool.length)];

                    // --- INTELLIGENT SELECTION HEURISTICS ---

                    // Calculate the density we currently need: (Required Protein / Required Calories)
                    // If we need 5g pro and 100 cal, density is 0.05.
                    const safeNeedCal = Math.max(50, needCal); 
                    const targetDensity = Math.max(0, needPro) / safeNeedCal; 

                    // 1. OVERSHOOT PROTECTION:
                    // If we have met or are very close to protein goal (needPro < 5g), 
                    // we strictly punish high protein items.
                    if (needPro <= 5) {
                        // We basically want carbs/fats (low efficiency).
                        // If candidate is "Protein Dense" (e.g. > 10g per 100kcal -> 0.1), try to reject.
                        if (candidate.efficiency > 0.10) {
                             // High probability to reroll to find something less protein dense
                             let rerolls = 3;
                             while (rerolls > 0 && candidate.efficiency > 0.10) {
                                candidate = pool[Math.floor(Math.random() * pool.length)];
                                rerolls--;
                             }
                        }
                    } 
                    // 2. RATIO MATCHING:
                    // If we still have a significant gap to fill, try to match the ratio.
                    // This prevents picking Whey (0.25) when we need Banana (0.05).
                    else {
                        const densityDiff = candidate.efficiency - targetDensity;

                        // If candidate is WAY more protein dense than needed (e.g. diff > 0.15)
                        if (densityDiff > 0.15) {
                             // Try to find a better fit that isn't so protein heavy
                             let rerolls = 3;
                             while (rerolls > 0) {
                                const next = pool[Math.floor(Math.random() * pool.length)];
                                // If the next one is closer to our target density, take it
                                if (Math.abs(next.efficiency - targetDensity) < Math.abs(densityDiff)) {
                                    candidate = next;
                                    break; 
                                }
                                rerolls--;
                             }
                        }
                    }

                    // 3. Variety Check (Hard constraint on 3rd duplicate)
                    if ((counts[candidate.id] || 0) >= 2) {
                         candidate = pool[Math.floor(Math.random() * pool.length)];
                         if ((counts[candidate.id] || 0) >= 2) continue; 
                    }

                    // 4. Hard Overage Check
                    if (currentCombo.length > 0 && (currentCal + candidate.cal > remainingCal + MAX_OVERAGE_HARD)) {
                        continue; 
                    }

                    currentCombo.push(candidate);
                    currentCal += candidate.cal;
                    currentPro += candidate.pro;
                    counts[candidate.id] = (counts[candidate.id] || 0) + 1;
                }

                if (currentCombo.length === 0) continue;

                // --- SCORING ---
                let score = 0;
                const finalCal = currentCal;
                const finalPro = currentPro;

                // 1. Protein Goal
                const missingPro = Math.max(0, remainingPro - finalPro);
                if (mode !== 'cal') {
                    score += missingPro * PENALTY_MISSED_PRO;

                    // NEW: Penalty for Excess Protein
                    const excessPro = Math.max(0, finalPro - remainingPro);
                    if (excessPro > 0) {
                        // Base penalty for going over
                        score += excessPro * PENALTY_EXCESS_PRO;
                        // Heavy penalty for significant overshoots (>15g over)
                        if (excessPro > 15) {
                            score += (excessPro - 15) * PENALTY_EXCESS_PRO_HEAVY;
                        }
                    }
                }

                // 2. Calorie Goal
                const diffCal = finalCal - remainingCal;
                if (diffCal > 0) {
                    score += (diffCal * PENALTY_PER_CAL_OVER) + (Math.pow(diffCal, 2) * PENALTY_PER_CAL_OVER_SQ);
                } else {
                    score += Math.abs(diffCal) * 2; 
                }

                // 3. Variety / Duplicates
                Object.values(counts).forEach(count => {
                    if (count === 2) score += PENALTY_DUPLICATE_2;
                    if (count >= 3) score += PENALTY_DUPLICATE_3_PLUS * (count - 2);
                });

                // 4. Repetition Penalty (Regenerate Variety)
                const currentSig = currentCombo.map(i => i.id).sort().join('|');
                if (currentSig === lastSignatureRef.current) {
                    score += PENALTY_SAME_AS_LAST;
                }

                if (currentCombo.length === 0) score = Infinity;

                if (score < bestScore) {
                    bestScore = score;
                    bestCombo = currentCombo;
                }
            }

            // Save signature
            if (bestCombo.length > 0) {
                lastSignatureRef.current = bestCombo.map(i => i.id).sort().join('|');
            }

            setSuggestions(bestCombo.map((item, idx) => ({
                item,
                selected: true,
                uniqueKey: `${item.id}-${idx}-${Date.now()}`
            })));
            setIsLoading(false);
        }, 50);
    };

    const toggleItem = (index: number) => {
        setSuggestions(prev => prev.map((s, i) => 
            i === index ? { ...s, selected: !s.selected } : s
        ));
    };

    const handleLog = () => {
        const toLog = suggestions.filter(s => s.selected).map(s => s.item);
        if (toLog.length > 0) {
            onLogSuggestions(toLog);
            onClose();
        }
    };

    useEffect(() => {
        if (isOpen) {
            lastSignatureRef.current = ''; 
            generate();
        }
    }, [isOpen]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
            <div className="bg-white/95 backdrop-blur-xl p-6 rounded-[32px] shadow-2xl w-full max-w-sm animate-pop-in max-h-[85vh] flex flex-col">
                <div className="flex justify-between items-center mb-6 shrink-0">
                    <div className="flex items-center gap-2">
                        <div className="bg-yellow-100 p-2 rounded-xl text-yellow-600">
                            <Flame className="w-5 h-5" filled />
                        </div>
                        <h3 className="text-xl font-bold text-gray-800">Smart Suggestion</h3>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>

                <div className="mb-4 shrink-0">
                    <div className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-2">Remaining Goal</div>
                    <div className="flex items-center gap-4">
                        <div className="font-black text-2xl text-gray-800">{remainingCal > 0 ? remainingCal : 0} <span className="text-sm text-gray-400 font-bold">kcal</span></div>
                        <div className="w-px h-6 bg-gray-200"></div>
                        <div className="font-black text-2xl text-protein">{remainingPro > 0 ? remainingPro : 0} <span className="text-sm text-gray-400 font-bold">g</span></div>
                    </div>
                </div>

                {/* Suggestions List */}
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2 mb-4">
                    {isLoading ? (
                        <div className="flex justify-center py-10">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-accent"></div>
                        </div>
                    ) : suggestions.length > 0 ? (
                        suggestions.map((wrapper, idx) => (
                            <button 
                                key={wrapper.uniqueKey} 
                                onClick={() => toggleItem(idx)}
                                className={`w-full text-left bg-white p-4 rounded-2xl flex justify-between items-center shadow-sm border transition-all duration-200 group ${
                                    wrapper.selected 
                                    ? 'border-gray-100 opacity-100' 
                                    : 'border-transparent bg-gray-50 opacity-50 grayscale-[0.5]'
                                }`}
                            >
                                <div>
                                    <div className={`font-bold transition-colors ${wrapper.selected ? 'text-gray-800' : 'text-gray-500'}`}>
                                        {wrapper.item.label}
                                    </div>
                                    <div className="text-xs text-gray-500">
                                        {wrapper.item.cal} kcal • {wrapper.item.pro}g pro
                                    </div>
                                </div>
                                <div className={`h-6 w-6 rounded-full flex items-center justify-center text-xs font-bold transition-all ${
                                    wrapper.selected 
                                    ? 'bg-green-100 text-green-600 scale-100' 
                                    : 'bg-gray-200 text-gray-400 scale-90'
                                }`}>
                                    {wrapper.selected ? '✓' : ''}
                                </div>
                            </button>
                        ))
                    ) : (
                        <div className="text-center py-8 text-gray-400 text-sm">
                            Couldn't find a good combination from your saved meals to fit this gap. Try creating more presets!
                        </div>
                    )}
                </div>

                {/* Result Summary */}
                <div className="bg-gray-50 rounded-2xl p-4 mb-4 shrink-0 border border-gray-100">
                    <div className="flex justify-between items-center mb-1">
                        <span className="text-xs font-bold text-gray-500">SELECTED TOTAL</span>
                        <button onClick={generate} className="text-xs font-bold text-accent hover:underline">Regenerate</button>
                    </div>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-xl font-black ${totals.cal > remainingCal + 100 ? 'text-red-500' : 'text-gray-800'}`}>
                            {totals.cal}
                        </span>
                        <span className="text-xs font-bold text-gray-400">kcal</span>

                        <span className="mx-2 text-gray-300">|</span>

                        <span className={`text-xl font-black ${Math.abs(remainingPro - totals.pro) > 10 ? 'text-indigo-400' : 'text-protein'}`}>
                            {totals.pro}
                        </span>
                        <span className="text-xs font-bold text-gray-400">pro</span>
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-3 shrink-0">
                    <button 
                        onClick={onClose}
                        className="py-3 rounded-2xl font-bold text-gray-500 hover:bg-gray-100 transition"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={handleLog}
                        disabled={suggestions.filter(s => s.selected).length === 0}
                        className={`py-3 rounded-2xl font-bold text-white transition shadow-lg ${
                            suggestions.filter(s => s.selected).length > 0 
                            ? 'bg-black active:scale-95' 
                            : 'bg-gray-300'
                        }`}
                    >
                        Log Selected
                    </button>
                </div>
            </div>
        </div>
    );
};

