function useAvgPeriodStats(statsPeriod: string, history: LoggedMeal[], currentDate: Date): {cal: number, pro: number, daysLogged: number} {
    const [avgStats, setAvgStats] = useState({ cal: 0, pro: 0, daysLogged: 0 });
    const [total, setTotal] = useState({ cal: 0, pro: 0 })
    const [daysLogged, setDaysLogged] = useState(0)

    useEffect(() => {
        let periodStart: Date;
        if (statsPeriod === 'week') {
          const today = currentDate;
          const day = today.getDay();
          const diff = today.getDate() - day + (day === 0 ? -6:1); // adjust when day is sunday
          periodStart = new Date(today.setDate(diff));
        } else if (statsPeriod === 'month') {
          periodStart = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
        } else {
          return setAvgStats({cal:0, pro: 0, daysLogged: 0});
        }

        const filteredHistory = history.filter(log => {
          const logDate = new Date(log.date);
          return logDate >= periodStart;
        });

        const total = filteredHistory.reduce((acc, d) => ({ cal: acc.cal + d.cal, pro: acc.pro + d.pro }), { cal: 0, pro: 0 });

        setDaysLogged(filteredHistory.length)
        setTotal({
            cal: Math.round(total.cal),
            pro: Math.round(total.pro),
        })

    }, [history, statsPeriod, currentDate]);

    useEffect(() => {
      if (!daysLogged) return;
      setAvgStats({
        cal: Math.round(total.cal / daysLogged),
        pro: Math.round(total.pro / daysLogged),
        daysLogged
      })
    }, [total, daysLogged])

    return avgStats;
  }
